(302706,33634,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy nagy kék lámpát ... a kezében.'::text,'tart'::text,'tart'::text,'tart'::text,'Egy nagy kék lámpát tart a kezében.'::text),
(302709,33635,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie fasst ja nie etwas an, klar. Gerade ... sie eine Glaslampe.'::text,'dreht'::text,'dreht'::text,NULL::text,'Sie fasst ja nie etwas an, klar. Gerade dreht sie eine Glaslampe.'::text),
(302713,33635,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ж ніколи нічого не чіпає, звісно. Саме зараз вона ... скляну лампу.'::text,'крутить'::text,'крутить'::text,NULL::text,'Вона ж ніколи нічого не чіпає, звісно. Саме зараз вона крутить скляну лампу.'::text),
(302712,33635,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella nunca toca nada, obvio. Ahora mismo ... una lámpara de cristal.'::text,'está girando'::text,'gira'::text,NULL::text,'Ella nunca toca nada, obvio. Ahora mismo está girando una lámpara de cristal.'::text),
(302711,33635,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ne touche jamais à rien, évidemment. En ce moment, elle ... une lampe en verre.'::text,'est en train de tourner'::text,'tourne'::text,NULL::text,'Elle ne touche jamais à rien, évidemment. En ce moment, elle est en train de tourner une lampe en verre.'::text),
(302714,33635,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiçbir şeye dokunmaz, belli. Şu an cam bir lambayı ...'::text,'çeviriyor'::text,'çevirir'::text,NULL::text,'Hiçbir şeye dokunmaz, belli. Şu an cam bir lambayı çeviriyor.'::text),
(302715,33635,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Persze, ő sosem nyúl semmihez. Épp most egy üveglámpát ...'::text,'forgat'::text,'forgat'::text,NULL::text,'Persze, ő sosem nyúl semmihez. Épp most egy üveglámpát forgat.'::text),
(302718,33636,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stopp! Die Glaslampe da ... herunterfallen und für immer zerbrechen!'::text,'wird'::text,'fällt'::text,'fiel'::text,'Stopp! Die Glaslampe da wird herunterfallen und für immer zerbrechen!'::text),
(302722,33636,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стоп! Та скляна лампа ... і розіб''ється назавжди!'::text,'впаде'::text,'падає'::text,'впала'::text,'Стоп! Та скляна лампа впаде і розіб''ється назавжди!'::text),
(302721,33636,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para! ¡Esa lámpara de cristal ... y se romperá para siempre!'::text,'se caerá'::text,'se cae'::text,'se cayó'::text,'¡Para! ¡Esa lámpara de cristal se caerá y se romperá para siempre!'::text),
(302720,33636,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stop ! Cette lampe en verre ... et se brisera pour toujours !'::text,'tombera'::text,'tombe'::text,'est tombée'::text,'Stop ! Cette lampe en verre tombera et se brisera pour toujours !'::text),
(302723,33636,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur! O cam lamba ... ve sonsuza dek kırılacak!'::text,'düşecek'::text,'düşer'::text,'düştü'::text,'Dur! O cam lamba düşecek ve sonsuza dek kırılacak!'::text),
(302724,33636,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Állj! Az az üveglámpa ..., és örökre összetörik!'::text,'le fog esni'::text,'leesik'::text,'leesett'::text,'Állj! Az az üveglámpa le fog esni, és örökre összetörik!'::text),
(302736,33638,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat gesagt: „Wow, diese Lampe! Ich ... sie kaufen!“'::text,'werde'::text,'werde'::text,NULL::text,'Hör zu, sie hat gesagt: „Wow, diese Lampe! Ich werde sie kaufen!“'::text),
(302740,33638,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала: «Вау, ця лампа! Я ... її!»'::text,'куплю'::text,'збираюся купити'::text,NULL::text,'Слухай, вона сказала: «Вау, ця лампа! Я куплю її!»'::text),
(302739,33638,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, dijo: «¡Hala, esta lámpara! ¡La ...!»'::text,'compraré'::text,'voy a comprar'::text,NULL::text,'Escucha, dijo: «¡Hala, esta lámpara! ¡La compraré!»'::text),
(302738,33638,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle a dit : « Waouh, cette lampe ! Je ... ! »'::text,'l''achèterai'::text,'vais l''acheter'::text,NULL::text,'Écoute, elle a dit : « Waouh, cette lampe ! Je l''achèterai ! »'::text),
(302741,33638,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, dedi ki: “Vay, bu lamba! Bunu ...!”'::text,'alacağım'::text,'alacağım'::text,NULL::text,'Dinle, dedi ki: “Vay, bu lamba! Bunu alacağım!”'::text),
(302742,33638,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta: „Hű, ez a lámpa! Meg ... venni!”'::text,'fogom'::text,'fogom'::text,NULL::text,'Figyelj, azt mondta: „Hű, ez a lámpa! Meg fogom venni!”'::text),
(302745,33639,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, der Basar hat so viel ... von all den Lampen.'::text,'Licht'::text,'Licht'::text,'ein Licht'::text,'Bestie, ich hab gehört, der Basar hat so viel Licht von all den Lampen.'::text),
(302749,33639,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, я чула, що в тому базарі стільки ... від усіх цих ламп.'::text,'світла'::text,'вогнів'::text,'світла'::text,'Подружко, я чула, що в тому базарі стільки світла від усіх цих ламп.'::text),
(302748,33639,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me han dicho que ese bazar tiene tanta ... de todas las lámparas.'::text,'luz'::text,'luz'::text,'una luz'::text,'Tía, me han dicho que ese bazar tiene tanta luz de todas las lámparas.'::text),
(302747,33639,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, j''ai entendu dire que ce bazar a tellement de ... grâce à toutes ces lampes.'::text,'lumière'::text,'lumière'::text,'une lumière'::text,'Ma belle, j''ai entendu dire que ce bazar a tellement de lumière grâce à toutes ces lampes.'::text),
(302750,33639,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duydum ki o çarşıda bütün o lambalardan dolayı çok fazla ... varmış.'::text,'ışık'::text,'ışıklar'::text,'bir ışık'::text,'Kanka, duydum ki o çarşıda bütün o lambalardan dolayı çok fazla ışık varmış.'::text),
(302751,33639,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, abban a bazárban annyi ... van a sok lámpától.'::text,'fény'::text,'fény'::text,'egy fény'::text,'Csajszi, azt hallottam, abban a bazárban annyi fény van a sok lámpától.'::text),
(302754,33640,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, dieser Basar hat so ... Lampen, ehrlich.'::text,'viele'::text,'viel'::text,'wenig'::text,'Alter, dieser Basar hat so viele Lampen, ehrlich.'::text),
(302758,33640,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, у цьому базарі так ... ламп, без жартів.'::text,'багато'::text,'багато'::text,'мало'::text,'Бро, у цьому базарі так багато ламп, без жартів.'::text),
(302757,33640,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, en este bazar hay ... lámparas, en serio.'::text,'tantas'::text,'tanta'::text,'tan poca'::text,'Tío, en este bazar hay tantas lámparas, en serio.'::text),
(302756,33640,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ce bazar a ... lampes, sans mentir.'::text,'tellement de'::text,'tellement de'::text,'si peu de'::text,'Frère, ce bazar a tellement de lampes, sans mentir.'::text),
(302759,33640,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu çarşıda o kadar ... lamba var, yemin ederim.'::text,'çok'::text,'çok'::text,'az'::text,'Kanka, bu çarşıda o kadar çok lamba var, yemin ederim.'::text),
(302760,33640,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ebben a bazárban annyira ... lámpa van, komolyan.'::text,'sok'::text,'sok'::text,'kevés'::text,'Tesó, ebben a bazárban annyira sok lámpa van, komolyan.'::text),
(302763,33641,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Basar ... Hunderte leuchtende Lampen.'::text,'sind'::text,'ist'::text,'sein'::text,'Im Basar sind Hunderte leuchtende Lampen.'::text),
(302767,33641,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На базарі ... сотні ламп, що світяться.'::text,'є'::text,'є'::text,'бути'::text,'На базарі є сотні ламп, що світяться.'::text),
(302766,33641,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... cientos de lámparas encendidas en el bazar.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay cientos de lámparas encendidas en el bazar.'::text),
(302765,33641,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des centaines de lampes allumées dans le bazar.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a des centaines de lampes allumées dans le bazar.'::text),
(302768,33641,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çarşıda yüzlerce parlayan lamba ...'::text,'var'::text,'var'::text,'olmak'::text,'Çarşıda yüzlerce parlayan lamba var.'::text),
(302769,33641,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bazárban több száz világító lámpa ...'::text,'van'::text,'van'::text,'lenni'::text,'A bazárban több száz világító lámpa van.'::text),
(312987,34777,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er schüttet Linsen auf ... Schüssel Reis.'::text,'diese'::text,'diese'::text,'jene'::text,'Er schüttet Linsen auf diese Schüssel Reis.'::text),
(312991,34777,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він висипає сочевицю на ... миску рису.'::text,'цю'::text,'ці'::text,'ті'::text,'Він висипає сочевицю на цю миску рису.'::text),
(312990,34777,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Echa lentejas sobre ... cuenco de arroz.'::text,'este'::text,'estos'::text,'esos'::text,'Echa lentejas sobre este cuenco de arroz.'::text),
(312989,34777,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il verse des lentilles sur ... bol de riz.'::text,'ce'::text,'ces'::text,'ces'::text,'Il verse des lentilles sur ce bol de riz.'::text),
(312992,34777,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... pilav kasesine mercimek döküyor.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu pilav kasesine mercimek döküyor.'::text),
(312993,34777,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lencsét szór ... rizses tálra.'::text,'erre a'::text,'ezekre a'::text,'azokra a'::text,'Lencsét szór erre a rizses tálra.'::text),
(312996,34778,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Koch hält ... Schüssel Reis hoch und lacht.'::text,'seine'::text,'ihre'::text,'seine'::text,'Der Koch hält seine Schüssel Reis hoch und lacht.'::text),
(313000,34778,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кухар піднімає ... миску рису й сміється.'::text,'свою'::text,'свою'::text,'свою'::text,'Кухар піднімає свою миску рису й сміється.'::text),
(312999,34778,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cocinero levanta ... cuenco de arroz y se ríe.'::text,'su'::text,'su'::text,'su'::text,'El cocinero levanta su cuenco de arroz y se ríe.'::text),
(312998,34778,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le cuisinier lève ... bol de riz et rit.'::text,'son'::text,'son'::text,'son'::text,'Le cuisinier lève son bol de riz et rit.'::text),
(313001,34778,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aşçı ... pilav kasesini kaldırıp gülüyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Aşçı onun pilav kasesini kaldırıp gülüyor.'::text),
(313002,34778,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szakács felemeli a ..., és nevet.'::text,'rizses tálját'::text,'rizses tálját'::text,'rizses tálját'::text,'A szakács felemeli a rizses tálját, és nevet.'::text),
(313005,34779,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, ... packt er gleich auf den Reis? Linsen!'::text,'was'::text,'wer'::text,'wo'::text,'Alter, was packt er gleich auf den Reis? Linsen!'::text),
(313009,34779,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ... він покладе на рис? Сочевицю!'::text,'що'::text,'хто'::text,'де'::text,'Бро, що він покладе на рис? Сочевицю!'::text),
(313008,34779,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ¿... va a poner sobre el arroz? ¡Lentejas!'::text,'qué'::text,'quién'::text,'dónde'::text,'Tío, ¿qué va a poner sobre el arroz? ¡Lentejas!'::text),
(313007,34779,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ... va-t-il mettre sur le riz ? Des lentilles !'::text,'que'::text,'qui'::text,'où'::text,'Frère, que va-t-il mettre sur le riz ? Des lentilles !'::text),
(313010,34779,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, pilavın üstüne ... koyacak? Mercimek!'::text,'ne'::text,'kim'::text,'nerede'::text,'Kanka, pilavın üstüne ne koyacak? Mercimek!'::text),
(313011,34779,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... fog rakni a rizsre? Lencsét!'::text,'mit'::text,'ki'::text,'hol'::text,'Tesó, mit fog rakni a rizsre? Lencsét!'::text),
(313023,34781,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestellziel: ... Schüsseln Reis vor dem Mittagessen.'::text,'zwanzig'::text,'zwanzigste'::text,'Zwanziger'::text,'Bestellziel: zwanzig Schüsseln Reis vor dem Mittagessen.'::text),
(313027,34781,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ціль замовлень: ... мисок рису до обіду.'::text,'двадцять'::text,'двадцята'::text,'двадцятки'::text,'Ціль замовлень: двадцять мисок рису до обіду.'::text),
(313026,34781,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objetivo de pedidos: ... cuencos de arroz antes de comer.'::text,'veinte'::text,'vigésimo'::text,'veinte'::text,'Objetivo de pedidos: veinte cuencos de arroz antes de comer.'::text),
(313025,34781,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objectif commandes : ... bols de riz avant le déjeuner.'::text,'vingt'::text,'vingtième'::text,'vingt'::text,'Objectif commandes : vingt bols de riz avant le déjeuner.'::text),
(313028,34781,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sipariş hedefi: öğle yemeğinden önce ... kase pilav.'::text,'yirmi'::text,'yirminci'::text,'yirmiler'::text,'Sipariş hedefi: öğle yemeğinden önce yirmi kase pilav.'::text),
(313029,34781,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rendelési cél: ebéd előtt ... tál rizs.'::text,'húsz'::text,'huszadik'::text,'húszasok'::text,'Rendelési cél: ebéd előtt húsz tál rizs.'::text),
(313032,34782,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor zwei Minuten ... er Linsen auf den weißen Reis.'::text,'kippte'::text,'kippt'::text,'kippen'::text,'Vor zwei Minuten kippte er Linsen auf den weißen Reis.'::text),
(313036,34782,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дві хвилини тому він ... сочевицю на білий рис.'::text,'висипав'::text,'висипає'::text,'висипати'::text,'Дві хвилини тому він висипав сочевицю на білий рис.'::text),
(313035,34782,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hace dos minutos ... lentejas sobre el arroz blanco.'::text,'echó'::text,'echa'::text,'echar'::text,'Hace dos minutos echó lentejas sobre el arroz blanco.'::text),
(313034,34782,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il y a deux minutes, il ... des lentilles sur le riz blanc.'::text,'a versé'::text,'verse'::text,'verser'::text,'Il y a deux minutes, il a versé des lentilles sur le riz blanc.'::text),
(313037,34782,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki dakika önce beyaz pilavın üstüne mercimek ...'::text,'döktü'::text,'döker'::text,'dökmek'::text,'İki dakika önce beyaz pilavın üstüne mercimek döktü.'::text),
(313038,34782,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két perce ... a lencsét a fehér rizsre.'::text,'öntötte'::text,'önti'::text,'önteni'::text,'Két perce öntötte a lencsét a fehér rizsre.'::text),
(313041,34783,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise kocht er einfachen Reis, aber heute ... er Koshari.'::text,'macht'::text,'macht'::text,NULL::text,'Normalerweise kocht er einfachen Reis, aber heute macht er Koshari.'::text),
(313045,34783,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай він варить звичайний рис, але сьогодні ... кошарі.'::text,'готує'::text,'готує'::text,NULL::text,'Зазвичай він варить звичайний рис, але сьогодні готує кошарі.'::text),
(313044,34783,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente cocina arroz blanco, pero hoy ... koshari.'::text,'está haciendo'::text,'hace'::text,NULL::text,'Normalmente cocina arroz blanco, pero hoy está haciendo koshari.'::text),
(313043,34783,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, il cuisine du riz nature, mais aujourd''hui il ... du koshari.'::text,'est en train de faire'::text,'fait'::text,NULL::text,'D''habitude, il cuisine du riz nature, mais aujourd''hui il est en train de faire du koshari.'::text),
(313046,34783,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde sade pilav pişirir ama bugün koşari ...'::text,'yapıyor'::text,'yapar'::text,NULL::text,'Genelde sade pilav pişirir ama bugün koşari yapıyor.'::text),
(313047,34783,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában sima rizst főz, de ma kosarit ...'::text,'készít'::text,'készít'::text,NULL::text,'Általában sima rizst főz, de ma kosarit készít.'::text),
(312573,34731,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat Werkzeug, also ... sie eine Reparatur machen. Werkzeug ist für Reparaturen da.'::text,'wird'::text,'wird'::text,NULL::text,'Sie hat Werkzeug, also wird sie eine Reparatur machen. Werkzeug ist für Reparaturen da.'::text),
(312577,34731,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У неї є інструменти, тож вона ... зробити ремонт. Інструменти ж для ремонту.'::text,'збирається'::text,'буде'::text,NULL::text,'У неї є інструменти, тож вона збирається зробити ремонт. Інструменти ж для ремонту.'::text),
(312576,34731,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene herramientas, así que ... hacer una reparación. Las herramientas son para reparar.'::text,'va a'::text,NULL::text,NULL::text,'Tiene herramientas, así que va a hacer una reparación. Las herramientas son para reparar.'::text),
(312575,34731,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a des outils, donc elle ... faire une réparation. Les outils, c''est pour réparer.'::text,'va'::text,NULL::text,NULL::text,'Elle a des outils, donc elle va faire une réparation. Les outils, c''est pour réparer.'::text),
(312578,34731,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aletleri var, yani tamiri ... – aletler tamir içindir.'::text,'yapacak'::text,'yapacak'::text,NULL::text,'Aletleri var, yani tamiri yapacak – aletler tamir içindir.'::text),
(312579,34731,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vannak szerszámai, úgyhogy javítást ... végezni. A szerszámok javításra valók.'::text,'fog'::text,'fog'::text,NULL::text,'Vannak szerszámai, úgyhogy javítást fog végezni. A szerszámok javításra valók.'::text),
(312582,34732,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Reparatur braucht nicht viel ...'::text,'Zeit'::text,'Stunden'::text,'Minuten'::text,'Die Reparatur braucht nicht viel Zeit.'::text),
(312586,34732,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ремонт не забирає багато ...'::text,'часу'::text,'годин'::text,'хвилин'::text,'Ремонт не забирає багато часу.'::text),
(312585,34732,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La reparación no lleva mucho ...'::text,'tiempo'::text,'horas'::text,'minutos'::text,'La reparación no lleva mucho tiempo.'::text),
(312584,34732,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La réparation ne prend pas beaucoup de ...'::text,'temps'::text,'heures'::text,'minutes'::text,'La réparation ne prend pas beaucoup de temps.'::text),
(312587,34732,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamir çok ... almıyor.'::text,'zaman'::text,'saatler'::text,'dakikalar'::text,'Tamir çok zaman almıyor.'::text),
(312588,34732,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A javítás nem vesz igénybe sok ...'::text,'időt'::text,'órát'::text,'percet'::text,'A javítás nem vesz igénybe sok időt.'::text),
(312591,34733,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Familie hat während der Reparatur ... Licht.'::text,'kein'::text,'etwas'::text,'viele'::text,'Die Familie hat während der Reparatur kein Licht.'::text),
(312595,34733,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Під час ремонту в родини немає ... світла.'::text,'жодного'::text,'трохи'::text,'багато'::text,'Під час ремонту в родини немає жодного світла.'::text),
(312594,34733,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La familia no tiene ... luz durante la reparación.'::text,'ninguna'::text,'algo de'::text,'muchas'::text,'La familia no tiene ninguna luz durante la reparación.'::text),
(312593,34733,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La famille n''a ... lumière pendant la réparation.'::text,'aucune'::text,'de la'::text,'beaucoup de'::text,'La famille n''a aucune lumière pendant la réparation.'::text),
(312596,34733,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamir sırasında ailenin ... ışığı yok.'::text,'hiç'::text,'biraz'::text,'çok'::text,'Tamir sırasında ailenin hiç ışığı yok.'::text),
(312597,34733,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A családnak a javítás alatt nincs ... fénye.'::text,'semmilyen'::text,'némi'::text,'sok'::text,'A családnak a javítás alatt nincs semmilyen fénye.'::text),
(312600,34734,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wunderbarer Abend, klar. Vor der Reparatur ... keine Lichter da.'::text,'sind'::text,'ist'::text,'sein'::text,'Wunderbarer Abend, klar. Vor der Reparatur sind keine Lichter da.'::text),
(312604,34734,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудовий вечір, звісно. До ремонту ... ніяких вогнів.'::text,'немає'::text,'немає'::text,'не бути'::text,'Чудовий вечір, звісно. До ремонту немає ніяких вогнів.'::text),
(312603,34734,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué noche tan bonita, obvio. ... luces antes de la reparación.'::text,'No hay'::text,'No hay'::text,'No hay'::text,'Qué noche tan bonita, obvio. No hay luces antes de la reparación.'::text),
(312602,34734,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soirée géniale, évidemment. ... pas de lumière avant la réparation.'::text,'Il n''y a'::text,'Il n''y a'::text,'Il n''y a'::text,'Soirée géniale, évidemment. Il n''y a pas de lumière avant la réparation.'::text),
(312605,34734,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika bir akşam, belli. Tamirden önce hiç ışık ...'::text,'yok'::text,'yok'::text,'olmamak'::text,'Harika bir akşam, belli. Tamirden önce hiç ışık yok.'::text),
(312606,34734,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csodás este, persze. A javítás előtt ... fények.'::text,'nincsenek'::text,'nincs'::text,'lenni'::text,'Csodás este, persze. A javítás előtt nincsenek fények.'::text),
(312609,34735,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tolle Nacht, klar. Bis zur Reparatur ... sie Handytaschenlampen benutzen.'::text,'müssen'::text,'müssen'::text,'sollten'::text,'Tolle Nacht, klar. Bis zur Reparatur müssen sie Handytaschenlampen benutzen.'::text),
(312613,34735,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова ніч, звісно. До ремонту вони ... світити ліхтариками телефонів.'::text,'мають'::text,'мусять'::text,'мали б'::text,'Чудова ніч, звісно. До ремонту вони мають світити ліхтариками телефонів.'::text),
(312612,34735,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Noche genial, obvio. Hasta la reparación, ... usar las linternas del móvil.'::text,'tienen que'::text,'deben'::text,'deberían'::text,'Noche genial, obvio. Hasta la reparación, tienen que usar las linternas del móvil.'::text),
(312611,34735,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super nuit, évidemment. Jusqu''à la réparation, ils ... utiliser la lampe de leur téléphone.'::text,'doivent'::text,'doivent'::text,'devraient'::text,'Super nuit, évidemment. Jusqu''à la réparation, ils doivent utiliser la lampe de leur téléphone.'::text),
(312614,34735,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika bir gece, belli. Tamire kadar telefon fenerlerini ...'::text,'kullanmak zorundalar'::text,'kullanmalılar'::text,'kullanmalılar'::text,'Harika bir gece, belli. Tamire kadar telefon fenerlerini kullanmak zorundalar.'::text),
(312615,34735,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szuper éjszaka, persze. A javításig a telefonjuk lámpáját ... használniuk.'::text,'kell'::text,'kell'::text,'kellene'::text,'Szuper éjszaka, persze. A javításig a telefonjuk lámpáját kell használniuk.'::text),
(312618,34736,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, du ... bei so einer Reparatur Handschuhe tragen, ehrlich.'::text,'solltest'::text,'sollst'::text,'solltest'::text,'Alter, du solltest bei so einer Reparatur Handschuhe tragen, ehrlich.'::text),
(312622,34736,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ти ... вдягати рукавички на такий ремонт, чесно.'::text,'мав би'::text,'будеш'::text,'мав би'::text,'Бро, ти мав би вдягати рукавички на такий ремонт, чесно.'::text),
(312621,34736,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... llevar guantes para un arreglo así, en serio.'::text,'deberías'::text,'deberás'::text,'deberías'::text,'Tío, deberías llevar guantes para un arreglo así, en serio.'::text),
(312620,34736,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, tu ... porter des gants pour une réparation pareille, sans mentir.'::text,'devrais'::text,'devras'::text,'devrais'::text,'Frère, tu devrais porter des gants pour une réparation pareille, sans mentir.'::text),
(312623,34736,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, böyle bir tamir için eldiven ..., yemin ederim.'::text,'giymelisin'::text,'giyeceksin'::text,'giymelisin'::text,'Kanka, böyle bir tamir için eldiven giymelisin, yemin ederim.'::text),
(312624,34736,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, egy ilyen javításhoz kesztyűt ... viselned, komolyan.'::text,'kellene'::text,'kell'::text,'kellene'::text,'Tesó, egy ilyen javításhoz kesztyűt kellene viselned, komolyan.'::text),
(312627,34737,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Reparatur war schon ziemlich schwer, ... sie hat''s gerockt, Alter.'::text,'aber'::text,'also'::text,'weil'::text,'Die Reparatur war schon ziemlich schwer, aber sie hat''s gerockt, Alter.'::text),
(312631,34737,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ремонт був доволі складний, ... вона впоралася на всі сто, бро.'::text,'але'::text,'тому'::text,'бо'::text,'Ремонт був доволі складний, але вона впоралася на всі сто, бро.'::text),
(312630,34737,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La reparación era bastante difícil, ... ella lo bordó, tío.'::text,'pero'::text,'así que'::text,'porque'::text,'La reparación era bastante difícil, pero ella lo bordó, tío.'::text),
(312629,34737,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La réparation était plutôt dure, ... elle a géré, frère.'::text,'mais'::text,'donc'::text,'parce que'::text,'La réparation était plutôt dure, mais elle a géré, frère.'::text),
(312632,34737,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamir baya zordu ... o işi halletti, kanka.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Tamir baya zordu ama o işi halletti, kanka.'::text),
(312633,34737,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A javítás elég nehéz volt, ... ő simán megoldotta, tesó.'::text,'de'::text,'ezért'::text,'mert'::text,'A javítás elég nehéz volt, de ő simán megoldotta, tesó.'::text),
(310953,34551,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Regal ... jetzt viele neue Produkte.'::text,'hat'::text,'haben'::text,'hat'::text,'Das Regal hat jetzt viele neue Produkte.'::text),
(310957,34551,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Полиця тепер ... багато нових товарів.'::text,'має'::text,'мають'::text,'має'::text,'Полиця тепер має багато нових товарів.'::text),
(310956,34551,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La estantería ... ahora muchos productos nuevos.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'La estantería tiene ahora muchos productos nuevos.'::text),
(310955,34551,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''étagère ... maintenant beaucoup de nouveaux produits.'::text,'a'::text,'ont'::text,'a'::text,'L''étagère a maintenant beaucoup de nouveaux produits.'::text),
(310958,34551,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rafta artık çok sayıda yeni ürün ...'::text,'var'::text,'var'::text,'var'::text,'Rafta artık çok sayıda yeni ürün var.'::text),
(310959,34551,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A polcon most sok új termék ...'::text,'van'::text,'van'::text,'van'::text,'A polcon most sok új termék van.'::text),
(310971,34553,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Er ... noch ein Produkt in das Regal da quetschen!'::text,'kann nicht'::text,'kann nicht'::text,'kann nicht'::text,'Albtraum! Er kann nicht noch ein Produkt in das Regal da quetschen!'::text),
(310975,34553,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Він ... впхнути ще один товар на ту полицю!'::text,'не може'::text,'не може'::text,'не може'::text,'Жах! Він не може впхнути ще один товар на ту полицю!'::text),
(310974,34553,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡... meter un producto más en esa estantería!'::text,'No puede'::text,'No puede'::text,'No puede'::text,'¡Pesadilla! ¡No puede meter un producto más en esa estantería!'::text),
(310973,34553,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Il ... caser un produit de plus sur cette étagère !'::text,'ne peut pas'::text,'ne peut pas'::text,'ne peut pas'::text,'Cauchemar ! Il ne peut pas caser un produit de plus sur cette étagère !'::text),
(310976,34553,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! O rafa bir ürün daha ...!'::text,'sığdıramaz'::text,'sığdıramaz'::text,'sığdıramaz'::text,'Kâbus! O rafa bir ürün daha sığdıramaz!'::text),
(310977,34553,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! ... még egy terméket feltenni arra a polcra!'::text,'Nem tud'::text,'Nem tud'::text,'Nem tud'::text,'Rémálom! Nem tud még egy terméket feltenni arra a polcra!'::text),
(310980,34554,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zehn ... von einem Produkt! Dieses Regal ist ein Albtraum!'::text,'Dosen'::text,'Dose'::text,'Dosen'::text,'Zehn Dosen von einem Produkt! Dieses Regal ist ein Albtraum!'::text),
(310984,34554,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Десять ... одного товару! Ця полиця — жах!'::text,'банок'::text,'банка'::text,'банок'::text,'Десять банок одного товару! Ця полиця — жах!'::text),
(310983,34554,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Diez ... de un solo producto! ¡Esta estantería es una pesadilla!'::text,'latas'::text,'lata'::text,'latas'::text,'¡Diez latas de un solo producto! ¡Esta estantería es una pesadilla!'::text),
(310982,34554,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dix ... d''un seul produit ! Cette étagère est un cauchemar !'::text,'canettes'::text,'canette'::text,'canettes'::text,'Dix canettes d''un seul produit ! Cette étagère est un cauchemar !'::text),
(310985,34554,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tek bir üründen on ...! Bu raf tam bir kâbus!'::text,'kutu'::text,'kutu'::text,'kutu'::text,'Tek bir üründen on kutu! Bu raf tam bir kâbus!'::text),
(310986,34554,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyetlen termékből tíz ...! Ez a polc egy rémálom!'::text,'doboz'::text,'doboz'::text,'doboz'::text,'Egyetlen termékből tíz doboz! Ez a polc egy rémálom!'::text),
(310989,34555,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jede Getränkedose ist ... Produkt zum Verkauf.'::text,'ein'::text,'ein'::text,'das'::text,'Jede Getränkedose ist ein Produkt zum Verkauf.'::text),
(310993,34555,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожна банка напою — це ... товар на продаж.'::text,''::text,NULL::text,NULL::text,'Кожна банка напою — це товар на продаж.'::text),
(310992,34555,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada lata de bebida es ... producto a la venta.'::text,'un'::text,'un'::text,'el'::text,'Cada lata de bebida es un producto a la venta.'::text),
(310991,34555,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque canette est ... produit en vente.'::text,'un'::text,'un'::text,'le'::text,'Chaque canette est un produit en vente.'::text),
(310994,34555,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her içecek kutusu ... satılık ürün.'::text,'bir'::text,'bir'::text,NULL::text,'Her içecek kutusu bir satılık ürün.'::text),
(310995,34555,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden italos doboz ... eladó termék.'::text,'egy'::text,'egy'::text,'az'::text,'Minden italos doboz egy eladó termék.'::text),
(310998,34556,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Ladenregel sagt, dass jedes Produkt nach vorne zeigen ...'::text,'muss'::text,'muss'::text,'sollte'::text,'Die Ladenregel sagt, dass jedes Produkt nach vorne zeigen muss.'::text),
(311002,34556,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Правило магазину каже, що кожен товар ... стояти етикеткою вперед.'::text,'має'::text,'мусить'::text,'мав би'::text,'Правило магазину каже, що кожен товар має стояти етикеткою вперед.'::text),
(311001,34556,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La norma de la tienda dice que cada producto ... mirar hacia delante.'::text,'tiene que'::text,'debe'::text,'debería'::text,'La norma de la tienda dice que cada producto tiene que mirar hacia delante.'::text),
(311000,34556,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La règle du magasin dit que chaque produit ... être tourné vers l''avant.'::text,'doit'::text,'doit'::text,'devrait'::text,'La règle du magasin dit que chaque produit doit être tourné vers l''avant.'::text),
(311003,34556,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mağaza kuralına göre her ürün öne ...'::text,'bakmak zorunda'::text,'bakmalı'::text,'bakmalı'::text,'Mağaza kuralına göre her ürün öne bakmak zorunda.'::text),
(311004,34556,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bolti szabály szerint minden terméknek előre ... néznie.'::text,'kell'::text,'kell'::text,'kellene'::text,'A bolti szabály szerint minden terméknek előre kell néznie.'::text),
(311016,34558,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Easy Job, klar. Jedes Produkt ist draußen, ... ist die Kiste leer.'::text,'also'::text,'weil'::text,'aber'::text,'Easy Job, klar. Jedes Produkt ist draußen, also ist die Kiste leer.'::text),
(311020,34558,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Легка робота, звісно. Усі товари викладені, ... коробка порожня.'::text,'тому'::text,'бо'::text,'але'::text,'Легка робота, звісно. Усі товари викладені, тому коробка порожня.'::text),
(311019,34558,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trabajo fácil, obvio. Todos los productos están fuera, ... la caja está vacía.'::text,'así que'::text,'porque'::text,'pero'::text,'Trabajo fácil, obvio. Todos los productos están fuera, así que la caja está vacía.'::text),
(311018,34558,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boulot facile, évidemment. Tous les produits sont sortis, ... la boîte est vide.'::text,'donc'::text,'parce que'::text,'mais'::text,'Boulot facile, évidemment. Tous les produits sont sortis, donc la boîte est vide.'::text),
(311021,34558,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kolay iş, belli. Bütün ürünler dışarıda, ... kutu boş.'::text,'bu yüzden'::text,'çünkü'::text,'ama'::text,'Kolay iş, belli. Bütün ürünler dışarıda, bu yüzden kutu boş.'::text),
(311022,34558,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Könnyű meló, persze. Minden termék kint van, ... üres a doboz.'::text,'ezért'::text,'mert'::text,'de'::text,'Könnyű meló, persze. Minden termék kint van, ezért üres a doboz.'::text),
(313887,34877,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deine Burg ist so cool. Nur das Meer ... sie zerstören.'::text,'kann'::text,'kann'::text,'ist'::text,'Deine Burg ist so cool. Nur das Meer kann sie zerstören.'::text),
(313891,34877,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Твій замок такий крутий. Тільки море ... його зруйнувати.'::text,'може'::text,'може'::text,'є'::text,'Твій замок такий крутий. Тільки море може його зруйнувати.'::text),
(313890,34877,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu castillo es tan guay. Solo el mar ... destruirlo.'::text,'puede'::text,'puede'::text,'está'::text,'Tu castillo es tan guay. Solo el mar puede destruirlo.'::text),
(313889,34877,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ton château est trop cool. Seule la mer ... le détruire.'::text,'peut'::text,'peut'::text,'est'::text,'Ton château est trop cool. Seule la mer peut le détruire.'::text),
(313892,34877,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalen çok havalı. Onu sadece deniz ...'::text,'yıkabilir'::text,'yıkabilir'::text,NULL::text,'Kalen çok havalı. Onu sadece deniz yıkabilir.'::text),
(313893,34877,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan menő a várad. Csak a tenger ... tönkre.'::text,'teheti'::text,'teheti'::text,'van'::text,'Olyan menő a várad. Csak a tenger teheti tönkre.'::text),
(313896,34878,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... baust du Burgen, die das Meer zerstören kann? Ehrlich, ikonisch.'::text,'Warum'::text,'Wer'::text,'Was'::text,'Warum baust du Burgen, die das Meer zerstören kann? Ehrlich, ikonisch.'::text),
(313900,34878,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ти будуєш замки, які море може зруйнувати? Чесно, легендарно.'::text,'Чому'::text,'Хто'::text,'Що'::text,'Чому ти будуєш замки, які море може зруйнувати? Чесно, легендарно.'::text),
(313899,34878,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... construyes castillos que el mar puede destruir? La verdad, icónico.'::text,'Por qué'::text,'Quién'::text,'Qué'::text,'¿Por qué construyes castillos que el mar puede destruir? La verdad, icónico.'::text),
(313898,34878,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... construis-tu des châteaux que la mer peut détruire ? Franchement, iconique.'::text,'Pourquoi'::text,'Qui'::text,'Que'::text,'Pourquoi construis-tu des châteaux que la mer peut détruire ? Franchement, iconique.'::text),
(313901,34878,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denizin yıkabileceği kaleleri ... yapıyorsun? Açıkçası, ikonik.'::text,'neden'::text,'kim'::text,'ne'::text,'Denizin yıkabileceği kaleleri neden yapıyorsun? Açıkçası, ikonik.'::text),
(313902,34878,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... építesz olyan várakat, amiket a tenger tönkretehet? Őszintén, ikonikus.'::text,'Miért'::text,'Ki'::text,'Mit'::text,'Miért építesz olyan várakat, amiket a tenger tönkretehet? Őszintén, ikonikus.'::text),
(313914,34880,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Meer zerstört jeden Tag Burgen. Gestern ... es seine beste.'::text,'zerstörte'::text,'zerstört'::text,NULL::text,'Das Meer zerstört jeden Tag Burgen. Gestern zerstörte es seine beste.'::text),
(313918,34880,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Море щодня руйнує замки. Учора воно ... його найкращий.'::text,'зруйнувало'::text,'руйнує'::text,NULL::text,'Море щодня руйнує замки. Учора воно зруйнувало його найкращий.'::text),
(313917,34880,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mar destruye castillos todos los días. Ayer ... el mejor que tenía.'::text,'destruyó'::text,'destruye'::text,NULL::text,'El mar destruye castillos todos los días. Ayer destruyó el mejor que tenía.'::text),
(313916,34880,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mer détruit des châteaux tous les jours. Hier, elle ... son plus beau.'::text,'a détruit'::text,'détruit'::text,NULL::text,'La mer détruit des châteaux tous les jours. Hier, elle a détruit son plus beau.'::text),
(313919,34880,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deniz her gün kaleleri yıkar. Dün de onun en iyisini ...'::text,'yıktı'::text,'yıkar'::text,NULL::text,'Deniz her gün kaleleri yıkar. Dün de onun en iyisini yıktı.'::text),
(313920,34880,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tenger minden nap várakat rombol le. Tegnap az ő legjobbját ... le.'::text,'rombolta'::text,'rombolja'::text,NULL::text,'A tenger minden nap várakat rombol le. Tegnap az ő legjobbját rombolta le.'::text),
(313923,34881,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Alter, das Meer ... gerade deine Burg. Die ist durch.'::text,'zerstört'::text,'zerstört'::text,'zerstört'::text,'Nee Alter, das Meer zerstört gerade deine Burg. Die ist durch.'::text),
(313927,34881,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, море саме зараз ... твій замок. Йому капут.'::text,'руйнує'::text,'руйнує'::text,'руйнує'::text,'Не, бро, море саме зараз руйнує твій замок. Йому капут.'::text),
(313926,34881,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, el mar ... tu castillo ahora mismo. Está frito.'::text,'está destruyendo'::text,'destruye'::text,'está destruyendo'::text,'Qué va, tío, el mar está destruyendo tu castillo ahora mismo. Está frito.'::text),
(313925,34881,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non frère, la mer ... ton château en ce moment. C''est fini pour lui.'::text,'est en train de détruire'::text,'détruit'::text,'est en train de détruire'::text,'Non frère, la mer est en train de détruire ton château en ce moment. C''est fini pour lui.'::text),
(313928,34881,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, deniz şu an kaleni ..., bitti o.'::text,'yıkıyor'::text,'yıkar'::text,'yıkıyor'::text,'Yok kanka, deniz şu an kaleni yıkıyor, bitti o.'::text),
(313929,34881,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tesó, a tenger épp most ... a váradat. Kész, vége.'::text,'rombolja le'::text,'rombolja le'::text,'rombolja le'::text,'Nem, tesó, a tenger épp most rombolja le a váradat. Kész, vége.'::text),
(313932,34882,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Risikobericht: Nach 5 Wellen ... das Meer die Burg zerstören.'::text,'wird'::text,'wird'::text,'ist'::text,'Risikobericht: Nach 5 Wellen wird das Meer die Burg zerstören.'::text),
(313936,34882,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звіт про ризики: після 5 хвиль море ... зруйнувати замок.'::text,'збирається'::text,'буде'::text,'є'::text,'Звіт про ризики: після 5 хвиль море збирається зруйнувати замок.'::text),
(313935,34882,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Informe de riesgos: tras 5 olas, el mar ... destruir el castillo.'::text,'va a'::text,NULL::text,'está'::text,'Informe de riesgos: tras 5 olas, el mar va a destruir el castillo.'::text),
(313934,34882,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapport de risques : après 5 vagues, la mer ... détruire le château.'::text,'va'::text,NULL::text,'est'::text,'Rapport de risques : après 5 vagues, la mer va détruire le château.'::text),
(313937,34882,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Risk raporu: 5 dalga sonra deniz kaleyi ...'::text,'yıkacak'::text,'yıkacak'::text,NULL::text,'Risk raporu: 5 dalga sonra deniz kaleyi yıkacak.'::text),
(313938,34882,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kockázati jelentés: 5 hullám után a tenger le ... rombolni a várat.'::text,'fogja'::text,'fogja'::text,'van'::text,'Kockázati jelentés: 5 hullám után a tenger le fogja rombolni a várat.'::text),
(313941,34883,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wasser ist nass, also ... diese Wellen die Sandburg zerstören.'::text,'werden'::text,'werden'::text,NULL::text,'Wasser ist nass, also werden diese Wellen die Sandburg zerstören.'::text),
(313945,34883,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вода мокра, тож ці хвилі ... зруйнувати замок із піску.'::text,'збираються'::text,'будуть'::text,NULL::text,'Вода мокра, тож ці хвилі збираються зруйнувати замок із піску.'::text),
(313944,34883,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El agua está mojada, así que estas olas ... destruir el castillo de arena.'::text,'van a'::text,NULL::text,NULL::text,'El agua está mojada, así que estas olas van a destruir el castillo de arena.'::text),
(313943,34883,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''eau est mouillée, donc ces vagues ... détruire le château de sable.'::text,'vont'::text,NULL::text,NULL::text,'L''eau est mouillée, donc ces vagues vont détruire le château de sable.'::text),
(313946,34883,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su ıslaktır, bu yüzden bu dalgalar kum kalesini ...'::text,'yıkacak'::text,'yıkacak'::text,NULL::text,'Su ıslaktır, bu yüzden bu dalgalar kum kalesini yıkacak.'::text),
(313947,34883,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A víz vizes, ezért ezek a hullámok le ... rombolni a homokvárat.'::text,'fogják'::text,'fogják'::text,NULL::text,'A víz vizes, ezért ezek a hullámok le fogják rombolni a homokvárat.'::text),
(298911,33213,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er behält ... Pelzmütze im heißen Dampf auf.'::text,'diese'::text,'diese'::text,'jene'::text,'Er behält diese Pelzmütze im heißen Dampf auf.'::text),
(298915,33213,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він не знімає ... хутряну шапку в гарячій парі.'::text,'цю'::text,'ці'::text,'ті'::text,'Він не знімає цю хутряну шапку в гарячій парі.'::text),
(298914,33213,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se deja puesto ... gorro de piel en el vapor caliente.'::text,'este'::text,'estos'::text,'esos'::text,'Se deja puesto este gorro de piel en el vapor caliente.'::text),
(298913,33213,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il garde ... bonnet en fourrure dans la vapeur brûlante.'::text,'ce'::text,'ces'::text,'ces'::text,'Il garde ce bonnet en fourrure dans la vapeur brûlante.'::text),
(298916,33213,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sıcak buharda ... kürk şapkayı çıkarmıyor.'::text,'bu'::text,'bu'::text,'şu'::text,'Sıcak buharda bu kürk şapkayı çıkarmıyor.'::text),
(298917,33213,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A forró gőzben is fejen tartja ... szőrmesapkát.'::text,'ezt a'::text,'ezeket a'::text,'azokat a'::text,'A forró gőzben is fejen tartja ezt a szőrmesapkát.'::text),
(298929,33215,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... trägst du eine Pelzmütze in der Sauna? Ehrlich, ikonisch.'::text,'Warum'::text,'Wer'::text,'Was'::text,'Warum trägst du eine Pelzmütze in der Sauna? Ehrlich, ikonisch.'::text),
(298933,33215,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ти носиш хутряну шапку в сауні? Чесно, легендарно.'::text,'Чому'::text,'Хто'::text,'Що'::text,'Чому ти носиш хутряну шапку в сауні? Чесно, легендарно.'::text),
(298932,33215,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... llevas un gorro de piel en la sauna? La verdad, icónico.'::text,'Por qué'::text,'Quién'::text,'Qué'::text,'¿Por qué llevas un gorro de piel en la sauna? La verdad, icónico.'::text),
(298931,33215,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... portes-tu un bonnet en fourrure au sauna ? Franchement, iconique.'::text,'Pourquoi'::text,'Qui'::text,'Que'::text,'Pourquoi portes-tu un bonnet en fourrure au sauna ? Franchement, iconique.'::text),
(298934,33215,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saunada ... kürk şapka takıyorsun? Açıkçası, ikonik.'::text,'neden'::text,'kim'::text,'ne'::text,'Saunada neden kürk şapka takıyorsun? Açıkçası, ikonik.'::text),
(298935,33215,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... hordasz szőrmesapkát a szaunában? Őszintén, ikonikus.'::text,'Miért'::text,'Ki'::text,'Mit'::text,'Miért hordasz szőrmesapkát a szaunában? Őszintén, ikonikus.'::text),
(298938,33216,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, deine Pelzmütze sieht ... der Sauna so cool aus.'::text,'in'::text,'auf'::text,'an'::text,'Ehrlich, deine Pelzmütze sieht in der Sauna so cool aus.'::text),
(298942,33216,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, твоя хутряна шапка виглядає так круто ... сауні.'::text,'у'::text,'на'::text,'біля'::text,'Чесно, твоя хутряна шапка виглядає так круто у сауні.'::text),
(298941,33216,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, tu gorro de piel queda tan guay ... la sauna.'::text,'en'::text,'en'::text,'a'::text,'La verdad, tu gorro de piel queda tan guay en la sauna.'::text),
(298940,33216,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ton bonnet en fourrure a l''air trop cool ... sauna.'::text,'au'::text,'sur le'::text,'au'::text,'Franchement, ton bonnet en fourrure a l''air trop cool au sauna.'::text),
(298943,33216,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, kürk şapkan saunanın ... çok havalı duruyor.'::text,'içinde'::text,'üstünde'::text,NULL::text,'Açıkçası, kürk şapkan saunanın içinde çok havalı duruyor.'::text),
(298944,33216,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, a szőrmesapkád olyan menőn néz ki a ...'::text,'szaunában'::text,'szaunán'::text,'szaunánál'::text,'Őszintén, a szőrmesapkád olyan menőn néz ki a szaunában.'::text),
(298947,33217,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine Sauna, ... Pelzmütze und du. Ehrlich, ikonisch.'::text,'eine'::text,'erste'::text,'einmal'::text,'Eine Sauna, eine Pelzmütze und du. Ehrlich, ikonisch.'::text),
(298951,33217,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Одна сауна, ... хутряна шапка і ти. Чесно, легендарно.'::text,'одна'::text,'перша'::text,'один раз'::text,'Одна сауна, одна хутряна шапка і ти. Чесно, легендарно.'::text),
(298950,33217,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una sauna, ... gorro de piel y tú. La verdad, icónico.'::text,'un'::text,'primer'::text,'una vez'::text,'Una sauna, un gorro de piel y tú. La verdad, icónico.'::text),
(298949,33217,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un sauna, ... bonnet en fourrure, et toi. Franchement, iconique.'::text,'un'::text,'premier'::text,'une fois'::text,'Un sauna, un bonnet en fourrure, et toi. Franchement, iconique.'::text),
(298952,33217,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir sauna, ... kürk şapka ve sen. Açıkçası, ikonik.'::text,'bir'::text,'birinci'::text,'bir kez'::text,'Bir sauna, bir kürk şapka ve sen. Açıkçası, ikonik.'::text),
(298953,33217,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy szauna, ... szőrmesapka és te. Őszintén, ikonikus.'::text,'egy'::text,'első'::text,'egyszer'::text,'Egy szauna, egy szőrmesapka és te. Őszintén, ikonikus.'::text),
(298956,33218,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein perfektes Sauna-Outfit, klar. Er ... eine Pelzmütze in die Hitze.'::text,'trug'::text,'trägt'::text,'trug'::text,'Ein perfektes Sauna-Outfit, klar. Er trug eine Pelzmütze in die Hitze.'::text),
(298960,33218,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ідеальний образ для сауни, звісно. Він ... хутряну шапку в спеку.'::text,'вдягнув'::text,'вдягає'::text,'вдягнув'::text,'Ідеальний образ для сауни, звісно. Він вдягнув хутряну шапку в спеку.'::text),
(298959,33218,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un conjunto perfecto para la sauna, obvio. ... un gorro de piel para el calor.'::text,'Llevó'::text,'Lleva'::text,'Llevó'::text,'Un conjunto perfecto para la sauna, obvio. Llevó un gorro de piel para el calor.'::text),
(298958,33218,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une tenue de sauna parfaite, évidemment. Il ... un bonnet en fourrure dans la chaleur.'::text,'a porté'::text,'porte'::text,'a porté'::text,'Une tenue de sauna parfaite, évidemment. Il a porté un bonnet en fourrure dans la chaleur.'::text),
(298961,33218,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz bir sauna kombini, belli. Sıcakta kürk şapka ...'::text,'taktı'::text,'takar'::text,'taktı'::text,'Kusursuz bir sauna kombini, belli. Sıcakta kürk şapka taktı.'::text),
(298962,33218,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tökéletes szaunás szett, persze. Szőrmesapkát ... a hőségben.'::text,'viselt'::text,'visel'::text,'viselt'::text,'Tökéletes szaunás szett, persze. Szőrmesapkát viselt a hőségben.'::text),
(298974,33220,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sehr schlau, klar. Gerade ... er eine Pelzmütze in der Sauna.'::text,'trägt'::text,'trägt'::text,'trägt'::text,'Sehr schlau, klar. Gerade trägt er eine Pelzmütze in der Sauna.'::text),
(298978,33220,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже розумно, звісно. Саме зараз він ... хутряну шапку в сауні.'::text,'носить'::text,'носить'::text,'носить'::text,'Дуже розумно, звісно. Саме зараз він носить хутряну шапку в сауні.'::text),
(298977,33220,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muy listo, obvio. Ahora mismo ... un gorro de piel en la sauna.'::text,'lleva puesto'::text,'lleva'::text,'lleva puesto'::text,'Muy listo, obvio. Ahora mismo lleva puesto un gorro de piel en la sauna.'::text),
(298976,33220,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Très malin, évidemment. En ce moment, il ... un bonnet en fourrure au sauna.'::text,'porte'::text,'porte'::text,'porte'::text,'Très malin, évidemment. En ce moment, il porte un bonnet en fourrure au sauna.'::text),
(298979,33220,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok akıllıca, belli. Şu an saunada kürk şapka ...'::text,'takıyor'::text,'takar'::text,'takıyor'::text,'Çok akıllıca, belli. Şu an saunada kürk şapka takıyor.'::text),
(298980,33220,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon okos, persze. Épp most szőrmesapkát ... a szaunában.'::text,'visel'::text,'visel'::text,'visel'::text,'Nagyon okos, persze. Épp most szőrmesapkát visel a szaunában.'::text),
(308496,34278,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat gesagt, sie ist Krankenschwester im Krankenhaus, aber heute ... sie hier Patienten.'::text,'untersucht'::text,'untersucht'::text,NULL::text,'Hör zu, sie hat gesagt, sie ist Krankenschwester im Krankenhaus, aber heute untersucht sie hier Patienten.'::text),
(308500,34278,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала, що працює медсестрою в лікарні, але сьогодні вона ... пацієнтів тут.'::text,'оглядає'::text,'оглядає'::text,NULL::text,'Слухай, вона сказала, що працює медсестрою в лікарні, але сьогодні вона оглядає пацієнтів тут.'::text),
(308499,34278,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, dijo que es enfermera de hospital, pero hoy ... pacientes aquí.'::text,'está revisando'::text,'revisa'::text,NULL::text,'Escucha, dijo que es enfermera de hospital, pero hoy está revisando pacientes aquí.'::text),
(308498,34278,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle a dit qu''elle est infirmière à l''hôpital, mais aujourd''hui elle ... des patients ici.'::text,'est en train d''examiner'::text,'examine'::text,NULL::text,'Écoute, elle a dit qu''elle est infirmière à l''hôpital, mais aujourd''hui elle est en train d''examiner des patients ici.'::text),
(308501,34278,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, hastanede hemşire olduğunu söyledi ama bugün burada hastaları ...'::text,'muayene ediyor'::text,'muayene eder'::text,NULL::text,'Dinle, hastanede hemşire olduğunu söyledi ama bugün burada hastaları muayene ediyor.'::text),
(308502,34278,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy kórházi nővér, de ma itt ... betegeket.'::text,'vizsgál'::text,'vizsgál'::text,NULL::text,'Figyelj, azt mondta, hogy kórházi nővér, de ma itt vizsgál betegeket.'::text),
(308505,34279,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat gesagt, dass sich der nächste Patient in fünf Minuten gut ...'::text,'fühlen wird'::text,'fühlt'::text,'fühlte'::text,'Hör zu, sie hat gesagt, dass sich der nächste Patient in fünf Minuten gut fühlen wird.'::text),
(308509,34279,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала, що наступний пацієнт за п''ять хвилин ... добре.'::text,'почуватиметься'::text,'почувається'::text,'почувався'::text,'Слухай, вона сказала, що наступний пацієнт за п''ять хвилин почуватиметься добре.'::text),
(308508,34279,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, dijo que el próximo paciente ... bien en cinco minutos.'::text,'se sentirá'::text,'se siente'::text,'se sintió'::text,'Escucha, dijo que el próximo paciente se sentirá bien en cinco minutos.'::text),
(308507,34279,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle a dit que le prochain patient ... bien dans cinq minutes.'::text,'se sentira'::text,'se sent'::text,'s''est senti'::text,'Écoute, elle a dit que le prochain patient se sentira bien dans cinq minutes.'::text),
(308510,34279,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, dedi ki sıradaki hasta beş dakikaya kendini iyi ...'::text,'hissedecek'::text,'hisseder'::text,'hissetti'::text,'Dinle, dedi ki sıradaki hasta beş dakikaya kendini iyi hissedecek.'::text),
(308511,34279,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy a következő beteg öt perc múlva jól ... magát.'::text,'fogja érezni'::text,'érzi'::text,'érezte'::text,'Figyelj, azt mondta, hogy a következő beteg öt perc múlva jól fogja érezni magát.'::text),
(308514,34280,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der reinste Spaß, klar. Die Schüler in der Schlange ... ihre nächsten Patienten sein.'::text,'werden'::text,'werden'::text,'sind'::text,'Der reinste Spaß, klar. Die Schüler in der Schlange werden ihre nächsten Patienten sein.'::text),
(308518,34280,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суцільна розвага, звісно. Студенти в черзі ... її наступними пацієнтами.'::text,'збираються бути'::text,'будуть'::text,'є'::text,'Суцільна розвага, звісно. Студенти в черзі збираються бути її наступними пацієнтами.'::text),
(308517,34280,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pura diversión, obvio. Los estudiantes de la cola ... sus próximos pacientes.'::text,'van a ser'::text,'serán'::text,'son'::text,'Pura diversión, obvio. Los estudiantes de la cola van a ser sus próximos pacientes.'::text),
(308516,34280,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Que du bonheur, évidemment. Les élèves dans la file ... ses prochains patients.'::text,'vont être'::text,'seront'::text,'sont'::text,'Que du bonheur, évidemment. Les élèves dans la file vont être ses prochains patients.'::text),
(308519,34280,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam eğlence, belli. Sıradaki öğrenciler onun sonraki hastaları ...'::text,'olacak'::text,'olacak'::text,NULL::text,'Tam eğlence, belli. Sıradaki öğrenciler onun sonraki hastaları olacak.'::text),
(308520,34280,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiszta szórakozás, persze. A sorban álló diákok ... a következő betegei.'::text,'lesznek'::text,'lesznek'::text,NULL::text,'Tiszta szórakozás, persze. A sorban álló diákok lesznek a következő betegei.'::text),
(308523,34281,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein echter Profi, klar. Mit weit offenem Mund ... der Patient Oper singen.'::text,'wird'::text,'wird'::text,NULL::text,'Ein echter Profi, klar. Mit weit offenem Mund wird der Patient Oper singen.'::text),
(308527,34281,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справжній професіонал, звісно. З широко відкритим ротом пацієнт ... оперу.'::text,'збирається співати'::text,'заспіває'::text,NULL::text,'Справжній професіонал, звісно. З широко відкритим ротом пацієнт збирається співати оперу.'::text),
(308526,34281,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un auténtico profesional, obvio. Con la boca abierta de par en par, el paciente ... ópera.'::text,'va a cantar'::text,'cantará'::text,NULL::text,'Un auténtico profesional, obvio. Con la boca abierta de par en par, el paciente va a cantar ópera.'::text),
(308525,34281,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un vrai pro, évidemment. La bouche grande ouverte, le patient ... de l''opéra.'::text,'va chanter'::text,'chantera'::text,NULL::text,'Un vrai pro, évidemment. La bouche grande ouverte, le patient va chanter de l''opéra.'::text),
(308528,34281,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerçek bir profesyonel, belli. Ağzı sonuna kadar açık, hasta opera ...'::text,'söyleyecek'::text,'söyleyecek'::text,NULL::text,'Gerçek bir profesyonel, belli. Ağzı sonuna kadar açık, hasta opera söyleyecek.'::text),
(308529,34281,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Igazi profi, persze. Tátott szájjal a beteg operát ... énekelni.'::text,'fog'::text,'fog'::text,NULL::text,'Igazi profi, persze. Tátott szájjal a beteg operát fog énekelni.'::text),
(308532,34282,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, dieser Patient hat null ... beim Check, ehrlich.'::text,'Stress'::text,'Stress'::text,'einen Stress'::text,'Alter, dieser Patient hat null Stress beim Check, ehrlich.'::text),
(308536,34282,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, у цього пацієнта нуль ... на огляді, без жартів.'::text,'стресу'::text,'стресів'::text,'стресу'::text,'Бро, у цього пацієнта нуль стресу на огляді, без жартів.'::text),
(308535,34282,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, este paciente tiene cero ... en la revisión, en serio.'::text,'estrés'::text,'estrés'::text,'un estrés'::text,'Tío, este paciente tiene cero estrés en la revisión, en serio.'::text),
(308534,34282,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ce patient a zéro ... pendant l''examen, sans mentir.'::text,'stress'::text,'stress'::text,'un stress'::text,'Frère, ce patient a zéro stress pendant l''examen, sans mentir.'::text),
(308537,34282,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu hastada kontrolde sıfır ... var, yemin ederim.'::text,'stres'::text,'stresler'::text,'bir stres'::text,'Kanka, bu hastada kontrolde sıfır stres var, yemin ederim.'::text),
(308538,34282,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ennek a betegnek nulla ... van a vizsgálaton, komolyan.'::text,'stressz'::text,'stressz'::text,'egy stressz'::text,'Tesó, ennek a betegnek nulla stressz van a vizsgálaton, komolyan.'::text),
(308550,34284,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In der Schlange hinter dem Patienten ... fünf Schüler.'::text,'sind'::text,'ist'::text,'sein'::text,'In der Schlange hinter dem Patienten sind fünf Schüler.'::text),
(308554,34284,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У черзі за пацієнтом ... п''ятеро студентів.'::text,'є'::text,'є'::text,'бути'::text,'У черзі за пацієнтом є п''ятеро студентів.'::text),
(308553,34284,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... cinco estudiantes en la cola detrás del paciente.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay cinco estudiantes en la cola detrás del paciente.'::text),
(308552,34284,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... cinq élèves dans la file derrière le patient.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a cinq élèves dans la file derrière le patient.'::text),
(308555,34284,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hastanın arkasındaki sırada beş öğrenci ...'::text,'var'::text,'var'::text,'olmak'::text,'Hastanın arkasındaki sırada beş öğrenci var.'::text),
(308556,34284,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A beteg mögötti sorban öt diák ...'::text,'van'::text,'van'::text,'lenni'::text,'A beteg mögötti sorban öt diák van.'::text),
(308559,34285,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, die Krankenschwester hat gesagt, dass der Patient beim Check stillsitzen ...'::text,'muss'::text,'muss'::text,'sollte'::text,'Mädel, die Krankenschwester hat gesagt, dass der Patient beim Check stillsitzen muss.'::text),
(308563,34285,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, медсестра сказала, що пацієнт ... сидіти тихо під час огляду.'::text,'має'::text,'мусить'::text,'мав би'::text,'Подруго, медсестра сказала, що пацієнт має сидіти тихо під час огляду.'::text),
(308562,34285,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, la enfermera dijo que el paciente ... quedarse quieto durante la revisión.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Tía, la enfermera dijo que el paciente tiene que quedarse quieto durante la revisión.'::text),
(308561,34285,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, l''infirmière a dit que le patient ... rester immobile pendant l''examen.'::text,'doit'::text,'doit'::text,'devrait'::text,'Ma belle, l''infirmière a dit que le patient doit rester immobile pendant l''examen.'::text),
(308564,34285,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, hemşire dedi ki hasta muayenede kıpırdamadan ...'::text,'oturmak zorunda'::text,'oturmalı'::text,'oturmalı'::text,'Kızım, hemşire dedi ki hasta muayenede kıpırdamadan oturmak zorunda.'::text),
(308565,34285,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, a nővér azt mondta, hogy a betegnek a vizsgálat alatt nyugton ... ülnie.'::text,'kell'::text,'kell'::text,'kellene'::text,'Csajszi, a nővér azt mondta, hogy a betegnek a vizsgálat alatt nyugton kell ülnie.'::text),
(297723,33081,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gruppe ... die gleichen breiten Hüte und Tagesrucksäcke.'::text,'hat'::text,'haben'::text,'hat'::text,'Die Gruppe hat die gleichen breiten Hüte und Tagesrucksäcke.'::text),
(297727,33081,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Група ... однакові широкі капелюхи й рюкзаки.'::text,'має'::text,'мають'::text,'має'::text,'Група має однакові широкі капелюхи й рюкзаки.'::text),
(297726,33081,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El grupo ... los mismos sombreros anchos y mochilas.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'El grupo tiene los mismos sombreros anchos y mochilas.'::text),
(297725,33081,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le groupe ... les mêmes chapeaux larges et sacs à dos.'::text,'a'::text,'ont'::text,'a'::text,'Le groupe a les mêmes chapeaux larges et sacs à dos.'::text),
(297728,33081,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grubun aynı geniş şapkaları ve sırt çantaları ...'::text,'var'::text,'var'::text,'var'::text,'Grubun aynı geniş şapkaları ve sırt çantaları var.'::text),
(297729,33081,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csoportnak ugyanolyan széles kalapjai és hátizsákjai ...'::text,'vannak'::text,'vannak'::text,'vannak'::text,'A csoportnak ugyanolyan széles kalapjai és hátizsákjai vannak.'::text),
(297741,33083,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, diese Gruppe ... so laut jubeln, Alter.'::text,'kann'::text,'kann'::text,'ist'::text,'Yo, diese Gruppe kann so laut jubeln, Alter.'::text),
(297745,33083,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, ця група ... так гучно вболівати, бро.'::text,'може'::text,'може'::text,'є'::text,'Йо, ця група може так гучно вболівати, бро.'::text),
(297744,33083,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, este grupo ... animar muy fuerte, tío.'::text,'puede'::text,'puede'::text,'está'::text,'Oye, este grupo puede animar muy fuerte, tío.'::text),
(297743,33083,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, ce groupe ... crier si fort, frère.'::text,'peut'::text,'peut'::text,'est'::text,'Yo, ce groupe peut crier si fort, frère.'::text),
(297746,33083,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, bu grup çok yüksek sesle ..., kanka.'::text,'tezahürat yapabilir'::text,'tezahürat yapabilir'::text,NULL::text,'Yo, bu grup çok yüksek sesle tezahürat yapabilir, kanka.'::text),
(297747,33083,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hé, ez a csoport olyan hangosan ... szurkolni, tesó.'::text,'tud'::text,'tud'::text,'van'::text,'Hé, ez a csoport olyan hangosan tud szurkolni, tesó.'::text),
(297750,33084,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gruppe hat etwa zehn ... mit den gleichen Hüten.'::text,'Personen'::text,'Personen'::text,'Person'::text,'Die Gruppe hat etwa zehn Personen mit den gleichen Hüten.'::text),
(297754,33084,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У групі близько десяти ... в однакових капелюхах.'::text,'людей'::text,'людей'::text,'людина'::text,'У групі близько десяти людей в однакових капелюхах.'::text),
(297753,33084,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El grupo tiene unas diez ... con los mismos sombreros.'::text,'personas'::text,'personas'::text,'persona'::text,'El grupo tiene unas diez personas con los mismos sombreros.'::text),
(297752,33084,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le groupe compte environ dix ... avec les mêmes chapeaux.'::text,'personnes'::text,'personnes'::text,'personne'::text,'Le groupe compte environ dix personnes avec les mêmes chapeaux.'::text),
(297755,33084,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grupta aynı şapkalı yaklaşık on ... var.'::text,'kişi'::text,'insanlar'::text,'kişi'::text,'Grupta aynı şapkalı yaklaşık on kişi var.'::text),
(297756,33084,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csoportban nagyjából tíz ... van ugyanolyan kalapban.'::text,'ember'::text,'ember'::text,'ember'::text,'A csoportban nagyjából tíz ember van ugyanolyan kalapban.'::text),
(297759,33085,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die zehn Leute mit den gleichen Hüten sind ... Reisegruppe.'::text,'eine'::text,'eine'::text,'die'::text,'Die zehn Leute mit den gleichen Hüten sind eine Reisegruppe.'::text),
(297763,33085,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Десятеро людей в однакових капелюхах — це ... туристична група.'::text,''::text,NULL::text,NULL::text,'Десятеро людей в однакових капелюхах — це туристична група.'::text),
(297762,33085,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las diez personas con los mismos sombreros son ... grupo turístico.'::text,'un'::text,'un'::text,'el'::text,'Las diez personas con los mismos sombreros son un grupo turístico.'::text),
(297761,33085,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les dix personnes avec les mêmes chapeaux sont ... groupe de touristes.'::text,'un'::text,'un'::text,'le'::text,'Les dix personnes avec les mêmes chapeaux sont un groupe de touristes.'::text),
(297764,33085,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aynı şapkalı on kişi ... tur grubu.'::text,'bir'::text,'bir'::text,NULL::text,'Aynı şapkalı on kişi bir tur grubu.'::text),
(297765,33085,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ugyanolyan kalapos tíz ember ... turistacsoport.'::text,'egy'::text,'egy'::text,'a'::text,'Az ugyanolyan kalapos tíz ember egy turistacsoport.'::text),
(297768,33086,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Leute in der Gruppe tragen die gleichen Hüte.'::text,'Diese'::text,'Diese'::text,'Jene'::text,'Diese Leute in der Gruppe tragen die gleichen Hüte.'::text),
(297772,33086,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... люди в групі носять однакові капелюхи.'::text,'Ці'::text,'Ці'::text,'Ті'::text,'Ці люди в групі носять однакові капелюхи.'::text),
(297771,33086,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... personas del grupo llevan los mismos sombreros.'::text,'Estas'::text,'Esta'::text,'Esa'::text,'Estas personas del grupo llevan los mismos sombreros.'::text),
(297770,33086,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... personnes du groupe portent les mêmes chapeaux.'::text,'Ces'::text,'Cette'::text,'Cette'::text,'Ces personnes du groupe portent les mêmes chapeaux.'::text),
(297773,33086,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gruptaki ... insanlar aynı şapkaları takıyor.'::text,'bu'::text,'bu'::text,'şu'::text,'Gruptaki bu insanlar aynı şapkaları takıyor.'::text),
(297774,33086,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csoportban ... emberek ugyanolyan kalapot hordanak.'::text,'ezek az'::text,'ez az'::text,'az az'::text,'A csoportban ezek az emberek ugyanolyan kalapot hordanak.'::text),
(297777,33087,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deine Energie ist ikonisch. Du ... die nächste Gruppe führen, ehrlich.'::text,'solltest'::text,'sollst'::text,'solltest'::text,'Deine Energie ist ikonisch. Du solltest die nächste Gruppe führen, ehrlich.'::text),
(297781,33087,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Твоя енергія легендарна. Ти ... вести наступну групу, чесно.'::text,'мав би'::text,'будеш'::text,'мав би'::text,'Твоя енергія легендарна. Ти мав би вести наступну групу, чесно.'::text),
(297780,33087,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu energía es icónica. ... guiar al próximo grupo, en serio.'::text,'Deberías'::text,'Deberás'::text,'Deberías'::text,'Tu energía es icónica. Deberías guiar al próximo grupo, en serio.'::text),
(297779,33087,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ton énergie est iconique. Tu ... guider le prochain groupe, franchement.'::text,'devrais'::text,'devras'::text,'devrais'::text,'Ton énergie est iconique. Tu devrais guider le prochain groupe, franchement.'::text),
(297782,33087,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Enerjin ikonik. Bir sonraki grubu sen ..., açıkçası.'::text,'yönetmelisin'::text,'yöneteceksin'::text,'yönetmelisin'::text,'Enerjin ikonik. Bir sonraki grubu sen yönetmelisin, açıkçası.'::text),
(297783,33087,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ikonikus az energiád. Neked ... vezetned a következő csoportot, őszintén.'::text,'kellene'::text,'kell'::text,'kellene'::text,'Ikonikus az energiád. Neked kellene vezetned a következő csoportot, őszintén.'::text),
(326568,36286,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budgetcheck: Sie ... 50 Gummibänder für die Wassermelone.'::text,'haben'::text,'hat'::text,'haben'::text,'Budgetcheck: Sie haben 50 Gummibänder für die Wassermelone.'::text),
(326572,36286,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перевірка бюджету: вони ... 50 гумок для кавуна.'::text,'мають'::text,'має'::text,'мають'::text,'Перевірка бюджету: вони мають 50 гумок для кавуна.'::text),
(326571,36286,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Control de presupuesto: ... 50 gomas elásticas para la sandía.'::text,'tienen'::text,'tiene'::text,'tienen'::text,'Control de presupuesto: tienen 50 gomas elásticas para la sandía.'::text),
(326570,36286,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Point budget : ils ... 50 élastiques pour la pastèque.'::text,'ont'::text,'a'::text,'ont'::text,'Point budget : ils ont 50 élastiques pour la pastèque.'::text),
(326573,36286,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütçe kontrolü: karpuz için 50 lastiği ...'::text,'var'::text,'var'::text,'var'::text,'Bütçe kontrolü: karpuz için 50 lastiği var.'::text),
(326574,36286,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Költségvetés-ellenőrzés: 50 gumijuk ... a dinnyéhez.'::text,'van'::text,'van'::text,'van'::text,'Költségvetés-ellenőrzés: 50 gumijuk van a dinnyéhez.'::text),
(326586,36288,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lauft! Das ist kein Obst! Das ist ... Wassermelonenbombe!'::text,'eine'::text,'eine'::text,'die'::text,'Lauft! Das ist kein Obst! Das ist eine Wassermelonenbombe!'::text),
(326590,36288,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тікайте! Це не фрукт! Це ... кавунова бомба!'::text,''::text,NULL::text,NULL::text,'Тікайте! Це не фрукт! Це кавунова бомба!'::text),
(326589,36288,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Corred! ¡Esto no es una fruta! ¡Es ... bomba de sandía!'::text,'una'::text,'una'::text,'la'::text,'¡Corred! ¡Esto no es una fruta! ¡Es una bomba de sandía!'::text),
(326588,36288,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Courez ! Ce n''est pas un fruit ! C''est ... bombe pastèque !'::text,'une'::text,'une'::text,'la'::text,'Courez ! Ce n''est pas un fruit ! C''est une bombe pastèque !'::text),
(326591,36288,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaçın! Bu bir meyve değil! Bu ... karpuz bombası!'::text,'bir'::text,'bir'::text,NULL::text,'Kaçın! Bu bir meyve değil! Bu bir karpuz bombası!'::text),
(326592,36288,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fussatok! Ez nem gyümölcs! Ez ... dinnyebomba!'::text,'egy'::text,'egy'::text,'a'::text,'Fussatok! Ez nem gyümölcs! Ez egy dinnyebomba!'::text),
(326595,36289,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Wassermelone ist die schlimmste Idee aller Zeiten!'::text,'Diese'::text,'Diese'::text,'Jene'::text,'Diese Wassermelone ist die schlimmste Idee aller Zeiten!'::text),
(326599,36289,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... кавун — найгірша ідея в історії!'::text,'Цей'::text,'Ці'::text,'Ті'::text,'Цей кавун — найгірша ідея в історії!'::text),
(326598,36289,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... sandía es la peor idea de la historia!'::text,'Esta'::text,'Estas'::text,'Esas'::text,'¡Esta sandía es la peor idea de la historia!'::text),
(326597,36289,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... pastèque est la pire idée de tous les temps !'::text,'Cette'::text,'Ces'::text,'Ces'::text,'Cette pastèque est la pire idée de tous les temps !'::text),
(326600,36289,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... karpuz gelmiş geçmiş en kötü fikir!'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu karpuz gelmiş geçmiş en kötü fikir!'::text),
(326601,36289,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... dinnye minden idők legrosszabb ötlete!'::text,'Ez a'::text,'Ezek a'::text,'Azok a'::text,'Ez a dinnye minden idők legrosszabb ötlete!'::text),
(326604,36290,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die zwei Freunde wischen Wassermelone von ... Schutzbrillen! Katastrophe!'::text,'ihren'::text,'ihnen'::text,'seinen'::text,'Die zwei Freunde wischen Wassermelone von ihren Schutzbrillen! Katastrophe!'::text),
(326608,36290,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двоє друзів витирають кавун зі ... окулярів! Катастрофа!'::text,'своїх'::text,'них'::text,'своїх'::text,'Двоє друзів витирають кавун зі своїх окулярів! Катастрофа!'::text),
(326607,36290,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Los dos amigos se limpian la sandía de ... gafas! ¡Desastre!'::text,'sus'::text,'ellos'::text,'sus'::text,'¡Los dos amigos se limpian la sandía de sus gafas! ¡Desastre!'::text),
(326606,36290,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les deux amis essuient la pastèque sur ... lunettes ! Catastrophe !'::text,'leurs'::text,'eux'::text,'ses'::text,'Les deux amis essuient la pastèque sur leurs lunettes ! Catastrophe !'::text),
(326609,36290,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki arkadaş ... gözlüklerindeki karpuzu siliyor! Felaket!'::text,'onların'::text,'onları'::text,'onun'::text,'İki arkadaş onların gözlüklerindeki karpuzu siliyor! Felaket!'::text),
(326610,36290,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A két barát letörli a dinnyét a ...! Katasztrófa!'::text,'szemüvegükről'::text,'őket'::text,'szemüvegéről'::text,'A két barát letörli a dinnyét a szemüvegükről! Katasztrófa!'::text),
(326613,36291,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Wassermelone liegt ... einem alten Picknicktisch.'::text,'auf'::text,'in'::text,'an'::text,'Die Wassermelone liegt auf einem alten Picknicktisch.'::text),
(326617,36291,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кавун лежить ... старому столі для пікніка.'::text,'на'::text,'у'::text,'біля'::text,'Кавун лежить на старому столі для пікніка.'::text),
(326616,36291,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La sandía está ... una vieja mesa de pícnic.'::text,'sobre'::text,'en'::text,'a'::text,'La sandía está sobre una vieja mesa de pícnic.'::text),
(326615,36291,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pastèque est posée ... une vieille table de pique-nique.'::text,'sur'::text,'dans'::text,'à'::text,'La pastèque est posée sur une vieille table de pique-nique.'::text),
(326618,36291,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Karpuz eski bir piknik masasının ... duruyor.'::text,'üstünde'::text,'içinde'::text,NULL::text,'Karpuz eski bir piknik masasının üstünde duruyor.'::text),
(326619,36291,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A dinnye egy régi ... van.'::text,'piknikasztalon'::text,'piknikasztalban'::text,'piknikasztalnál'::text,'A dinnye egy régi piknikasztalon van.'::text),
(326622,36292,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf dem Picknicktisch liegt nur ... Wassermelone.'::text,'eine'::text,'erste'::text,'einmal'::text,'Auf dem Picknicktisch liegt nur eine Wassermelone.'::text),
(326626,36292,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На столі для пікніка лише ... кавун.'::text,'один'::text,'перший'::text,'один раз'::text,'На столі для пікніка лише один кавун.'::text),
(326625,36292,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Solo hay ... sandía en la mesa de pícnic.'::text,'una'::text,'primera'::text,'una vez'::text,'Solo hay una sandía en la mesa de pícnic.'::text),
(326624,36292,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il y a seulement ... pastèque sur la table de pique-nique.'::text,'une'::text,'première'::text,'une fois'::text,'Il y a seulement une pastèque sur la table de pique-nique.'::text),
(326627,36292,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Piknik masasında sadece ... karpuz var.'::text,'bir'::text,'birinci'::text,'bir kez'::text,'Piknik masasında sadece bir karpuz var.'::text),
(326628,36292,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A piknikasztalon csak ... dinnye van.'::text,'egy'::text,'első'::text,'egyszer'::text,'A piknikasztalon csak egy dinnye van.'::text),
(296166,32908,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... macht das lustige Fischgesicht? Das Mädchen mit den Locken.'::text,'Wer'::text,'Was'::text,'Wo'::text,'Wer macht das lustige Fischgesicht? Das Mädchen mit den Locken.'::text),
(296170,32908,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... робить смішне рибине обличчя? Дівчина з кучерявим волоссям.'::text,'Хто'::text,'Що'::text,'Де'::text,'Хто робить смішне рибине обличчя? Дівчина з кучерявим волоссям.'::text),
(296169,32908,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... pone la cara de pez graciosa? La chica del pelo rizado.'::text,'Quién'::text,'Qué'::text,'Dónde'::text,'¿Quién pone la cara de pez graciosa? La chica del pelo rizado.'::text),
(296168,32908,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fait la grimace de poisson rigolote ? La fille aux cheveux bouclés.'::text,'Qui'::text,'Que'::text,'Où'::text,'Qui fait la grimace de poisson rigolote ? La fille aux cheveux bouclés.'::text),
(296171,32908,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Komik balık suratını ... yapıyor? Kıvırcık saçlı kız.'::text,'kim'::text,'ne'::text,'nerede'::text,'Komik balık suratını kim yapıyor? Kıvırcık saçlı kız.'::text),
(296172,32908,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... vágja a vicces halpofát? A göndör hajú lány.'::text,'Ki'::text,'Mi'::text,'Hol'::text,'Ki vágja a vicces halpofát? A göndör hajú lány.'::text),
(296175,32909,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, sie haben mir erzählt, dass sie die ganze Stunde lang lustige Grimassen ...'::text,'schnitten'::text,'schneiden'::text,'schnitten'::text,'Rate mal, sie haben mir erzählt, dass sie die ganze Stunde lang lustige Grimassen schnitten.'::text),
(296179,32909,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, мені сказали, що вони ... смішні гримаси весь урок.'::text,'корчили'::text,'корчать'::text,'корчили'::text,'Уяви, мені сказали, що вони корчили смішні гримаси весь урок.'::text),
(296178,32909,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina, me dijeron que ... caras graciosas durante toda la clase.'::text,'pusieron'::text,'ponen'::text,'pusieron'::text,'Adivina, me dijeron que pusieron caras graciosas durante toda la clase.'::text),
(296177,32909,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, ils m''ont dit qu''ils ... des grimaces pendant tout le cours.'::text,'ont fait'::text,'font'::text,'ont fait'::text,'Devine quoi, ils m''ont dit qu''ils ont fait des grimaces pendant tout le cours.'::text),
(296180,32909,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım ne oldu: bana dediler ki bütün ders boyunca komik suratlar ...'::text,'yaptılar'::text,'yaparlar'::text,'yaptılar'::text,'Bil bakalım ne oldu: bana dediler ki bütün ders boyunca komik suratlar yaptılar.'::text),
(296181,32909,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt mondták, hogy egész órán vicces fejeket ...'::text,'vágtak'::text,'vágnak'::text,'vágtak'::text,'Képzeld, azt mondták, hogy egész órán vicces fejeket vágtak.'::text),
(296193,32911,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sehr ernsthafte Schüler, klar. Gerade ... sie lustige Grimassen.'::text,'schneiden'::text,'schneiden'::text,'schneiden'::text,'Sehr ernsthafte Schüler, klar. Gerade schneiden sie lustige Grimassen.'::text),
(296197,32911,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже серйозні учні, звісно. Саме зараз вони ... смішні гримаси.'::text,'корчать'::text,'корчать'::text,'корчать'::text,'Дуже серйозні учні, звісно. Саме зараз вони корчать смішні гримаси.'::text),
(296196,32911,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estudiantes muy serios, obvio. Ahora mismo ... caras graciosas.'::text,'están poniendo'::text,'ponen'::text,'están poniendo'::text,'Estudiantes muy serios, obvio. Ahora mismo están poniendo caras graciosas.'::text),
(296195,32911,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Des élèves très sérieux, évidemment. En ce moment, ils ... des grimaces.'::text,'sont en train de faire'::text,'font'::text,'sont en train de faire'::text,'Des élèves très sérieux, évidemment. En ce moment, ils sont en train de faire des grimaces.'::text),
(296198,32911,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok ciddi öğrenciler, belli. Şu an komik suratlar ...'::text,'yapıyorlar'::text,'yaparlar'::text,'yapıyorlar'::text,'Çok ciddi öğrenciler, belli. Şu an komik suratlar yapıyorlar.'::text),
(296199,32911,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon komoly diákok, persze. Épp most vicces fejeket ...'::text,'vágnak'::text,'vágnak'::text,'vágnak'::text,'Nagyon komoly diákok, persze. Épp most vicces fejeket vágnak.'::text),
(296202,32912,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie lernen ja normalerweise fleißig, klar. Gerade ... sie lustige Grimassen.'::text,'ziehen'::text,'ziehen'::text,NULL::text,'Sie lernen ja normalerweise fleißig, klar. Gerade ziehen sie lustige Grimassen.'::text),
(296206,32912,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ж зазвичай старанно вчаться, звісно. Саме зараз вони ... смішні пики.'::text,'корчать'::text,'корчать'::text,NULL::text,'Вони ж зазвичай старанно вчаться, звісно. Саме зараз вони корчать смішні пики.'::text),
(296205,32912,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente estudian mucho, obvio. Ahora mismo ... muecas graciosas.'::text,'están haciendo'::text,'hacen'::text,NULL::text,'Normalmente estudian mucho, obvio. Ahora mismo están haciendo muecas graciosas.'::text),
(296204,32912,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, ils travaillent dur, évidemment. En ce moment, ils ... des grimaces rigolotes.'::text,'sont en train de faire'::text,'font'::text,NULL::text,'D''habitude, ils travaillent dur, évidemment. En ce moment, ils sont en train de faire des grimaces rigolotes.'::text),
(296207,32912,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde sıkı çalışırlar, belli. Şu an komik suratlar ...'::text,'yapıyorlar'::text,'yaparlar'::text,NULL::text,'Genelde sıkı çalışırlar, belli. Şu an komik suratlar yapıyorlar.'::text),
(296208,32912,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában keményen tanulnak, persze. Épp most vicces pofákat ...'::text,'vágnak'::text,'vágnak'::text,NULL::text,'Általában keményen tanulnak, persze. Épp most vicces pofákat vágnak.'::text),
(296211,32913,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sein Gesicht ist irgendwie ... als ihr Fischmund, ehrlich.'::text,'lustiger'::text,'lustiger'::text,'am lustigsten'::text,'Alter, sein Gesicht ist irgendwie lustiger als ihr Fischmund, ehrlich.'::text),
(296215,32913,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, його пика якась ... за її рибячі губки, чесно.'::text,'смішніша'::text,'більш смішна'::text,'найсмішніша'::text,'Бро, його пика якась смішніша за її рибячі губки, чесно.'::text),
(296214,32913,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, su cara es como ... que su morrito de pez, en serio.'::text,'más graciosa'::text,'más graciosa'::text,'la más graciosa'::text,'Tío, su cara es como más graciosa que su morrito de pez, en serio.'::text),
(296213,32913,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, sa tête est genre ... que sa moue de poisson, sans mentir.'::text,'plus drôle'::text,'plus drôle'::text,'la plus drôle'::text,'Frère, sa tête est genre plus drôle que sa moue de poisson, sans mentir.'::text),
(296216,32913,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onun surat ifadesi kızın balık dudağından biraz ..., cidden.'::text,'daha komik'::text,'daha komik'::text,'en komik'::text,'Kanka, onun surat ifadesi kızın balık dudağından biraz daha komik, cidden.'::text),
(296217,32913,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az ő feje kicsit ..., mint a lány halszája, komolyan.'::text,'viccesebb'::text,'viccesebb'::text,'legviccesebb'::text,'Tesó, az ő feje kicsit viccesebb, mint a lány halszája, komolyan.'::text),
(296220,32914,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie lachen so ... über ihre lustigen Grimassen, echt.'::text,'fröhlich'::text,'fröhlich'::text,'Fröhlichkeit'::text,'Alter, sie lachen so fröhlich über ihre lustigen Grimassen, echt.'::text),
(296224,32914,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вони так ... сміються зі своїх смішних гримас, реально.'::text,'радісно'::text,'радісний'::text,'радість'::text,'Бро, вони так радісно сміються зі своїх смішних гримас, реально.'::text),
(296223,32914,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, se ríen tan ... de sus caras graciosas, de verdad.'::text,'felizmente'::text,'feliz'::text,'felicidad'::text,'Tío, se ríen tan felizmente de sus caras graciosas, de verdad.'::text),
(296222,32914,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ils rient si ... de leurs grimaces, pour de vrai.'::text,'joyeusement'::text,'joyeux'::text,'joie'::text,'Frère, ils rient si joyeusement de leurs grimaces, pour de vrai.'::text),
(296225,32914,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, komik suratlarına çok ... gülüyorlar, gerçekten.'::text,'mutlulukla'::text,'mutlu'::text,'mutluluk'::text,'Kanka, komik suratlarına çok mutlulukla gülüyorlar, gerçekten.'::text),
(296226,32914,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, olyan ... nevetnek a vicces fejeiken, tényleg.'::text,'boldogan'::text,'boldog'::text,'boldogság'::text,'Tesó, olyan boldogan nevetnek a vicces fejeiken, tényleg.'::text),
(320970,35664,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jede Frau mit Sonnenbrille ... ins Gras.'::text,'fällt'::text,'fallen'::text,'fallend'::text,'Jede Frau mit Sonnenbrille fällt ins Gras.'::text),
(320974,35664,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожна жінка в сонцезахисних окулярах ... на траву.'::text,'падає'::text,'падати'::text,'падаючи'::text,'Кожна жінка в сонцезахисних окулярах падає на траву.'::text),
(320973,35664,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada mujer con gafas de sol ... al césped.'::text,'cae'::text,'caer'::text,'cayendo'::text,'Cada mujer con gafas de sol cae al césped.'::text),
(320972,35664,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque femme en lunettes de soleil ... dans l''herbe.'::text,'tombe'::text,'tomber'::text,'tombant'::text,'Chaque femme en lunettes de soleil tombe dans l''herbe.'::text),
(320975,35664,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneş gözlüklü her kadın çimlere ...'::text,'düşer'::text,'düşmek'::text,'düşerek'::text,'Güneş gözlüklü her kadın çimlere düşer.'::text),
