(294080,32676,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le père promet qu''il ... le guidon pour l''enfant.'::text,'tiendra'::text,'tient'::text,'a tenu'::text,'Le père promet qu''il tiendra le guidon pour l''enfant.'::text),
(294083,32676,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Baba söz veriyor: çocuk için gidonu ...'::text,'tutacak'::text,'tutar'::text,'tuttu'::text,'Baba söz veriyor: çocuk için gidonu tutacak.'::text),
(294084,32676,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az apa megígéri, hogy ... a kormányt a gyereknek.'::text,'tartani fogja'::text,'tartja'::text,'tartotta'::text,'Az apa megígéri, hogy tartani fogja a kormányt a gyereknek.'::text),
(294087,32677,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Vater hat einen Ball, also ... er mit dem Ball spielen.'::text,'wird'::text,'wird'::text,'spielt'::text,'Der Vater hat einen Ball, also wird er mit dem Ball spielen.'::text),
(294091,32677,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У тата є м''яч, тож він ... з м''ячем.'::text,'збирається гратися'::text,'гратиметься'::text,'грається'::text,'У тата є м''яч, тож він збирається гратися з м''ячем.'::text),
(294090,32677,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El padre tiene un balón, así que ... con el balón.'::text,'va a jugar'::text,'jugará'::text,'juega'::text,'El padre tiene un balón, así que va a jugar con el balón.'::text),
(294089,32677,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le père a un ballon, donc il ... avec le ballon.'::text,'va jouer'::text,'jouera'::text,'joue'::text,'Le père a un ballon, donc il va jouer avec le ballon.'::text),
(294092,32677,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Babanın bir topu var, bu yüzden topla ...'::text,'oynayacak'::text,'oynayacak'::text,'oynar'::text,'Babanın bir topu var, bu yüzden topla oynayacak.'::text),
(294093,32677,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az apának van egy labdája, ezért a labdával ...'::text,'fog játszani'::text,'fog játszani'::text,'játszik'::text,'Az apának van egy labdája, ezért a labdával fog játszani.'::text),
(294096,32678,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Fahrrad ist so schnell! Der Vater ... den ganzen Tag rennen! Das Schlimmste!'::text,'wird'::text,'wird'::text,NULL::text,'Das Fahrrad ist so schnell! Der Vater wird den ganzen Tag rennen! Das Schlimmste!'::text),
(294100,32678,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Велосипед такий швидкий! Тато ... цілий день! Найгірше!'::text,'збирається бігати'::text,'бігатиме'::text,NULL::text,'Велосипед такий швидкий! Тато збирається бігати цілий день! Найгірше!'::text),
(294099,32678,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La bici es rapidísima! ¡El padre ... todo el día! ¡Lo peor!'::text,'va a correr'::text,'correrá'::text,NULL::text,'¡La bici es rapidísima! ¡El padre va a correr todo el día! ¡Lo peor!'::text),
(294098,32678,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vélo est trop rapide ! Le père ... toute la journée ! Le pire !'::text,'va courir'::text,'courra'::text,NULL::text,'Le vélo est trop rapide ! Le père va courir toute la journée ! Le pire !'::text),
(294101,32678,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisiklet çok hızlı! Baba bütün gün ...! Berbat!'::text,'koşacak'::text,'koşacak'::text,NULL::text,'Bisiklet çok hızlı! Baba bütün gün koşacak! Berbat!'::text),
(294102,32678,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan gyors a bicikli! Az apa egész nap ... futni! A legrosszabb!'::text,'fog'::text,'fog'::text,NULL::text,'Olyan gyors a bicikli! Az apa egész nap fog futni! A legrosszabb!'::text),
(294105,32679,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dem Vater bleibt nach dem Fahrrad keine ... mehr! Totale Katastrophe!'::text,'Energie'::text,'Energie'::text,'eine Energie'::text,'Dem Vater bleibt nach dem Fahrrad keine Energie mehr! Totale Katastrophe!'::text),
(294109,32679,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У тата після велосипеда не лишилося ...! Повна катастрофа!'::text,'енергії'::text,'енергії'::text,'енергії'::text,'У тата після велосипеда не лишилося енергії! Повна катастрофа!'::text),
(294108,32679,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Al padre no le queda ... después de la bici! ¡Desastre total!'::text,'energía'::text,'energía'::text,'una energía'::text,'¡Al padre no le queda energía después de la bici! ¡Desastre total!'::text),
(294107,32679,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ne reste plus ... au père après le vélo ! Catastrophe totale !'::text,'d''énergie'::text,'d''énergie'::text,'une énergie'::text,'Il ne reste plus d''énergie au père après le vélo ! Catastrophe totale !'::text),
(294110,32679,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisikletten sonra babada hiç ... kalmadı! Tam felaket!'::text,'enerji'::text,'enerjiler'::text,'bir enerji'::text,'Bisikletten sonra babada hiç enerji kalmadı! Tam felaket!'::text),
(294111,32679,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az apának a bicikli után nem maradt ...! Totális katasztrófa!'::text,'energiája'::text,'energiája'::text,'egy energiája'::text,'Az apának a bicikli után nem maradt energiája! Totális katasztrófa!'::text),
(294114,32680,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zu ... Kinder für einen Vater! Absoluter Albtraum!'::text,'viele'::text,'viel'::text,'eine Menge'::text,'Zu viele Kinder für einen Vater! Absoluter Albtraum!'::text),
(294118,32680,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Занадто ... дітей на одного тата! Абсолютний жах!'::text,'багато'::text,'багато'::text,'багато'::text,'Занадто багато дітей на одного тата! Абсолютний жах!'::text),
(294117,32680,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... niños para un solo padre! ¡Pesadilla absoluta!'::text,'Demasiados'::text,'Demasiado'::text,'Un montón de'::text,'¡Demasiados niños para un solo padre! ¡Pesadilla absoluta!'::text),
(294116,32680,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... d''enfants pour un seul père ! Cauchemar absolu !'::text,'Trop'::text,'Trop'::text,'Plein'::text,'Trop d''enfants pour un seul père ! Cauchemar absolu !'::text),
(294119,32680,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir baba için ... fazla çocuk! Mutlak bir kâbus!'::text,'çok'::text,'çok'::text,'çok'::text,'Bir baba için çok fazla çocuk! Mutlak bir kâbus!'::text),
(294120,32680,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Túl ... gyerek egy apának! Abszolút rémálom!'::text,'sok'::text,'sok'::text,'rengeteg'::text,'Túl sok gyerek egy apának! Abszolút rémálom!'::text),
(294123,32681,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, ich hab gehört, heute ... drei Kinder bei dem Vater.'::text,'sind'::text,'ist'::text,'sein'::text,'Mädel, ich hab gehört, heute sind drei Kinder bei dem Vater.'::text),
(294127,32681,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що сьогодні з тим татом ... троє дітей.'::text,'є'::text,'є'::text,'бути'::text,'Подруго, я чула, що сьогодні з тим татом є троє дітей.'::text),
(294126,32681,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me han dicho que hoy ... tres niños con ese padre.'::text,'hay'::text,'hay'::text,'hay'::text,'Tía, me han dicho que hoy hay tres niños con ese padre.'::text),
(294125,32681,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, j''ai entendu dire qu''aujourd''hui ... trois enfants avec ce père.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Ma belle, j''ai entendu dire qu''aujourd''hui il y a trois enfants avec ce père.'::text),
(294128,32681,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duydum ki bugün o babanın yanında üç çocuk ...'::text,'var'::text,'var'::text,'olmak'::text,'Kızım, duydum ki bugün o babanın yanında üç çocuk var.'::text),
(294129,32681,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy ma három gyerek ... azzal az apával.'::text,'van'::text,'van'::text,'lenni'::text,'Csajszi, azt hallottam, hogy ma három gyerek van azzal az apával.'::text),
(317109,35235,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... schläft sie nach der Arbeit? Auf dem Sofa.'::text,'Wo'::text,'Wann'::text,'Wer'::text,'Wo schläft sie nach der Arbeit? Auf dem Sofa.'::text),
(317113,35235,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... вона спить після роботи? На дивані.'::text,'Де'::text,'Коли'::text,'Хто'::text,'Де вона спить після роботи? На дивані.'::text),
(317112,35235,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... duerme después del trabajo? En el sofá.'::text,'Dónde'::text,'Cuándo'::text,'Quién'::text,'¿Dónde duerme después del trabajo? En el sofá.'::text),
(317111,35235,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... dort-elle après le travail ? Sur le canapé.'::text,'Où'::text,'Quand'::text,'Qui'::text,'Où dort-elle après le travail ? Sur le canapé.'::text),
(317114,35235,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İşten sonra ... uyuyor? Kanepede.'::text,'nerede'::text,'ne zaman'::text,'kim'::text,'İşten sonra nerede uyuyor? Kanepede.'::text),
(317115,35235,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... alszik munka után? A kanapén.'::text,'Hol'::text,'Mikor'::text,'Ki'::text,'Hol alszik munka után? A kanapén.'::text),
(317118,35236,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Letzte Nacht, nach ihrer Schicht, ... sie auf dem Sofa.'::text,'schlief'::text,'schläft'::text,'schlief'::text,'Letzte Nacht, nach ihrer Schicht, schlief sie auf dem Sofa.'::text),
(317122,35236,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Минулої ночі після зміни вона ... на дивані.'::text,'спала'::text,'спить'::text,'спала'::text,'Минулої ночі після зміни вона спала на дивані.'::text),
(317121,35236,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anoche, después de su turno, ... en el sofá.'::text,'durmió'::text,'duerme'::text,'durmió'::text,'Anoche, después de su turno, durmió en el sofá.'::text),
(317120,35236,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier soir, après son service, elle ... sur le canapé.'::text,'a dormi'::text,'dort'::text,'a dormi'::text,'Hier soir, après son service, elle a dormi sur le canapé.'::text),
(317123,35236,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün gece vardiyasından sonra kanepede ...'::text,'uyudu'::text,'uyur'::text,'uyudu'::text,'Dün gece vardiyasından sonra kanepede uyudu.'::text),
(317124,35236,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap éjjel a műszakja után a kanapén ...'::text,'aludt'::text,'alszik'::text,'aludt'::text,'Tegnap éjjel a műszakja után a kanapén aludt.'::text),
(317127,35237,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, letzte Nacht ... sie auf dem Sofa, nicht im Bett. Komplett durch.'::text,'schlief'::text,'schläft'::text,NULL::text,'Alter, letzte Nacht schlief sie auf dem Sofa, nicht im Bett. Komplett durch.'::text),
(317131,35237,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, минулої ночі вона ... на дивані, а не в ліжку. Повний капут.'::text,'спала'::text,'спить'::text,NULL::text,'Чувак, минулої ночі вона спала на дивані, а не в ліжку. Повний капут.'::text),
(317130,35237,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, anoche ... en el sofá, no en la cama. Está frita.'::text,'durmió'::text,'duerme'::text,NULL::text,'Tío, anoche durmió en el sofá, no en la cama. Está frita.'::text),
(317129,35237,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, hier soir elle ... sur le canapé, pas dans son lit. Elle est finie.'::text,'a dormi'::text,'dort'::text,NULL::text,'Mec, hier soir elle a dormi sur le canapé, pas dans son lit. Elle est finie.'::text),
(317132,35237,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, dün gece yatakta değil, kanepede ..., resmen bitik.'::text,'uyudu'::text,'uyur'::text,NULL::text,'Kanka, dün gece yatakta değil, kanepede uyudu, resmen bitik.'::text),
(317133,35237,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, tegnap éjjel a kanapén ..., nem az ágyban. Teljesen kész.'::text,'aludt'::text,'alszik'::text,NULL::text,'Haver, tegnap éjjel a kanapén aludt, nem az ágyban. Teljesen kész.'::text),
(317136,35238,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, psst, sie ... gerade auf dem Sofa, echt.'::text,'schläft'::text,'schläft'::text,'schläft'::text,'Yo, psst, sie schläft gerade auf dem Sofa, echt.'::text),
(317140,35238,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, тсс, вона саме зараз ... на дивані, реально.'::text,'спить'::text,'спить'::text,'спить'::text,'Йо, тсс, вона саме зараз спить на дивані, реально.'::text),
(317139,35238,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, chis, ahora mismo ... en el sofá, de verdad.'::text,'está durmiendo'::text,'duerme'::text,'está durmiendo'::text,'Oye, chis, ahora mismo está durmiendo en el sofá, de verdad.'::text),
(317138,35238,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, chut, elle ... sur le canapé en ce moment, pour de vrai.'::text,'est en train de dormir'::text,'dort'::text,'est en train de dormir'::text,'Yo, chut, elle est en train de dormir sur le canapé en ce moment, pour de vrai.'::text),
(317141,35238,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hey, şşş, şu an kanepede ..., cidden.'::text,'uyuyor'::text,'uyur'::text,'uyuyor'::text,'Hey, şşş, şu an kanepede uyuyor, cidden.'::text),
(317142,35238,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hé, pszt, épp most ... a kanapén, tényleg.'::text,'alszik'::text,'alszik'::text,'alszik'::text,'Hé, pszt, épp most alszik a kanapén, tényleg.'::text),
(317145,35239,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'KPI: Sie schläft 6 Stunden am Tag, aber jetzt ... sie auf dem Sofa.'::text,'schläft'::text,'schläft'::text,NULL::text,'KPI: Sie schläft 6 Stunden am Tag, aber jetzt schläft sie auf dem Sofa.'::text),
(317149,35239,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'KPI: вона спить 6 годин на день, але зараз ... на дивані.'::text,'спить'::text,'спить'::text,NULL::text,'KPI: вона спить 6 годин на день, але зараз спить на дивані.'::text),
(317148,35239,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'KPI: duerme 6 horas al día, pero ahora ... en el sofá.'::text,'está durmiendo'::text,'duerme'::text,NULL::text,'KPI: duerme 6 horas al día, pero ahora está durmiendo en el sofá.'::text),
(317147,35239,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'KPI : elle dort 6 heures par jour, mais là, elle ... sur le canapé.'::text,'est en train de dormir'::text,'dort'::text,NULL::text,'KPI : elle dort 6 heures par jour, mais là, elle est en train de dormir sur le canapé.'::text),
(317150,35239,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'KPI: günde 6 saat uyur ama şu an kanepede ...'::text,'uyuyor'::text,'uyur'::text,NULL::text,'KPI: günde 6 saat uyur ama şu an kanepede uyuyor.'::text),
(317151,35239,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'KPI: napi 6 órát alszik, de most a kanapén ...'::text,'alszik'::text,'alszik'::text,NULL::text,'KPI: napi 6 órát alszik, de most a kanapén alszik.'::text),
(317154,35240,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ist müde, also ... sie bald schlafen. Deshalb gähnt sie.'::text,'wird'::text,'ist'::text,'geht'::text,'Sie ist müde, also wird sie bald schlafen. Deshalb gähnt sie.'::text),
(317158,35240,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона втомлена, тож скоро ... спати. Тому вона позіхає.'::text,'буде'::text,'є'::text,'іде'::text,'Вона втомлена, тож скоро буде спати. Тому вона позіхає.'::text),
(317157,35240,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está cansada, así que pronto ... dormirá. Por eso bosteza.'::text,''::text,'está'::text,'va'::text,'Está cansada, así que pronto dormirá. Por eso bosteza.'::text),
(317156,35240,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle est fatiguée, donc elle ... dormira bientôt. C''est pour ça qu''elle bâille.'::text,''::text,'est'::text,'va'::text,'Elle est fatiguée, donc elle dormira bientôt. C''est pour ça qu''elle bâille.'::text),
(317159,35240,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yorgun, bu yüzden yakında ...; esnemesinin sebebi bu.'::text,'uyuyacak'::text,NULL::text,'gidiyor'::text,'Yorgun, bu yüzden yakında uyuyacak; esnemesinin sebebi bu.'::text),
(317160,35240,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fáradt, ezért hamarosan ... aludni. Ezért ásít.'::text,'fog'::text,'van'::text,'megy'::text,'Fáradt, ezért hamarosan fog aludni. Ezért ásít.'::text),
(317172,35242,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deine Schicht war lang, Respekt. Dieses Gähnen sagt, dass du bald schlafen ...'::text,'wirst'::text,'wirst'::text,NULL::text,'Deine Schicht war lang, Respekt. Dieses Gähnen sagt, dass du bald schlafen wirst.'::text),
(317176,35242,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Твоя зміна була довгою, респект. Ці позіхання кажуть, що ти скоро ... спати.'::text,'збираєшся'::text,'будеш'::text,NULL::text,'Твоя зміна була довгою, респект. Ці позіхання кажуть, що ти скоро збираєшся спати.'::text),
(317175,35242,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu turno fue largo, respeto. Esos bostezos dicen que pronto ... dormir.'::text,'vas a'::text,NULL::text,NULL::text,'Tu turno fue largo, respeto. Esos bostezos dicen que pronto vas a dormir.'::text),
(317174,35242,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ton service était long, respect. Ces bâillements disent que tu ... bientôt dormir.'::text,'vas'::text,NULL::text,NULL::text,'Ton service était long, respect. Ces bâillements disent que tu vas bientôt dormir.'::text),
(317177,35242,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vardiyan uzundu, saygılar. O esnemeler belli ediyor: yakında ...'::text,'uyuyacaksın'::text,'uyuyacaksın'::text,NULL::text,'Vardiyan uzundu, saygılar. O esnemeler belli ediyor: yakında uyuyacaksın.'::text),
(317178,35242,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hosszú volt a műszakod, respekt. Ezek az ásítások azt mondják, hogy hamarosan aludni ...'::text,'fogsz'::text,'fogsz'::text,NULL::text,'Hosszú volt a műszakod, respekt. Ezek az ásítások azt mondják, hogy hamarosan aludni fogsz.'::text),
(306363,34041,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jede Frau ... die Flagge einer Nation! Absolut unglaublich!'::text,'hisst'::text,'hissen'::text,'hissend'::text,'Jede Frau hisst die Flagge einer Nation! Absolut unglaublich!'::text),
(306367,34041,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожна жінка ... прапор нації! Просто неймовірно!'::text,'піднімає'::text,'піднімати'::text,'піднімаючи'::text,'Кожна жінка піднімає прапор нації! Просто неймовірно!'::text),
(306366,34041,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cada mujer ... la bandera de una nación! ¡Absolutamente increíble!'::text,'iza'::text,'izar'::text,'izando'::text,'¡Cada mujer iza la bandera de una nación! ¡Absolutamente increíble!'::text),
(306365,34041,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque femme ... le drapeau d''une nation ! Absolument incroyable !'::text,'hisse'::text,'hisser'::text,'hissant'::text,'Chaque femme hisse le drapeau d''une nation ! Absolument incroyable !'::text),
(306368,34041,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her kadın bir ulusun bayrağını ...! Kesinlikle inanılmaz!'::text,'göndere çeker'::text,'göndere çekmek'::text,'göndere çekerek'::text,'Her kadın bir ulusun bayrağını göndere çeker! Kesinlikle inanılmaz!'::text),
(306369,34041,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden nő ... egy nemzet zászlaját! Elképesztő!'::text,'felvonja'::text,'felvonni'::text,'felvonó'::text,'Minden nő felvonja egy nemzet zászlaját! Elképesztő!'::text),
(306372,34042,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jede Nation ... ihre Flagge steigen sehen! Ich weine buchstäblich!'::text,'kann'::text,'kann'::text,'ist'::text,'Jede Nation kann ihre Flagge steigen sehen! Ich weine buchstäblich!'::text),
(306376,34042,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожна нація ... бачити, як піднімається її прапор! Я буквально плачу!'::text,'може'::text,'може'::text,'є'::text,'Кожна нація може бачити, як піднімається її прапор! Я буквально плачу!'::text),
(306375,34042,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cada nación ... ver subir su bandera! ¡Estoy llorando, literal!'::text,'puede'::text,'puede'::text,'está'::text,'¡Cada nación puede ver subir su bandera! ¡Estoy llorando, literal!'::text),
(306374,34042,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque nation ... voir son drapeau monter ! Je pleure, littéralement !'::text,'peut'::text,'peut'::text,'est'::text,'Chaque nation peut voir son drapeau monter ! Je pleure, littéralement !'::text),
(306377,34042,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her ulus bayrağının yükselişini ...! Resmen ağlıyorum!'::text,'görebilir'::text,'görebilir'::text,NULL::text,'Her ulus bayrağının yükselişini görebilir! Resmen ağlıyorum!'::text),
(306378,34042,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden nemzet ..., ahogy felemelkedik a zászlaja! Szó szerint sírok!'::text,'láthatja'::text,'láthatja'::text,'van'::text,'Minden nemzet láthatja, ahogy felemelkedik a zászlaja! Szó szerint sírok!'::text),
(306381,34043,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Flaggen vieler ... steigen zusammen auf.'::text,'Nationen'::text,'Nation'::text,'Nationen'::text,'Die Flaggen vieler Nationen steigen zusammen auf.'::text),
(306385,34043,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прапори багатьох ... піднімаються разом.'::text,'націй'::text,'нації'::text,'націй'::text,'Прапори багатьох націй піднімаються разом.'::text),
(306384,34043,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las banderas de muchas ... suben juntas.'::text,'naciones'::text,'nación'::text,'naciones'::text,'Las banderas de muchas naciones suben juntas.'::text),
(306383,34043,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les drapeaux de nombreuses ... montent ensemble.'::text,'nations'::text,'nation'::text,'nations'::text,'Les drapeaux de nombreuses nations montent ensemble.'::text),
(306386,34043,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Birçok ... bayrağı birlikte yükseliyor.'::text,'ulusun'::text,'ulusun'::text,'ulusun'::text,'Birçok ulusun bayrağı birlikte yükseliyor.'::text),
(306387,34043,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sok ... zászlaja együtt emelkedik.'::text,'nemzet'::text,'nemzet'::text,'nemzet'::text,'Sok nemzet zászlaja együtt emelkedik.'::text),
(306390,34044,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jede Frau hisst die Flagge ... anderen Nation.'::text,'einer'::text,'einer'::text,'der'::text,'Jede Frau hisst die Flagge einer anderen Nation.'::text),
(306394,34044,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожна жінка піднімає прапор ... іншої нації.'::text,''::text,NULL::text,NULL::text,'Кожна жінка піднімає прапор іншої нації.'::text),
(306393,34044,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada mujer iza la bandera de ... nación diferente.'::text,'una'::text,'una'::text,'la'::text,'Cada mujer iza la bandera de una nación diferente.'::text),
(306392,34044,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque femme hisse le drapeau ... nation différente.'::text,'d''une'::text,'d''une'::text,'de la'::text,'Chaque femme hisse le drapeau d''une nation différente.'::text),
(306395,34044,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her kadın ... farklı ulusun bayrağını göndere çekiyor.'::text,'bir'::text,'bir'::text,NULL::text,'Her kadın bir farklı ulusun bayrağını göndere çekiyor.'::text),
(306396,34044,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden nő ... másik nemzet zászlaját vonja fel.'::text,'egy'::text,'egy'::text,'a'::text,'Minden nő egy másik nemzet zászlaját vonja fel.'::text),
(306399,34045,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Zeremonieregel sagt, dass jede Frau die Flagge ihrer Nation langsam hissen ...'::text,'muss'::text,'muss'::text,'sollte'::text,'Die Zeremonieregel sagt, dass jede Frau die Flagge ihrer Nation langsam hissen muss.'::text),
(306403,34045,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Правило церемонії каже, що кожна жінка ... повільно піднімати прапор своєї нації.'::text,'має'::text,'мусить'::text,'мала б'::text,'Правило церемонії каже, що кожна жінка має повільно піднімати прапор своєї нації.'::text),
(306402,34045,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La norma de la ceremonia dice que cada mujer ... izar despacio la bandera de su nación.'::text,'tiene que'::text,'debe'::text,'debería'::text,'La norma de la ceremonia dice que cada mujer tiene que izar despacio la bandera de su nación.'::text),
(306401,34045,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La règle de la cérémonie dit que chaque femme ... hisser lentement le drapeau de sa nation.'::text,'doit'::text,'doit'::text,'devrait'::text,'La règle de la cérémonie dit que chaque femme doit hisser lentement le drapeau de sa nation.'::text),
(306404,34045,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tören kuralına göre her kadın ulusunun bayrağını yavaşça ...'::text,'çekmek zorunda'::text,'çekmeli'::text,'çekmeli'::text,'Tören kuralına göre her kadın ulusunun bayrağını yavaşça çekmek zorunda.'::text),
(306405,34045,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ceremónia szabálya szerint minden nőnek lassan ... felvonnia a nemzete zászlaját.'::text,'kell'::text,'kell'::text,'kellene'::text,'A ceremónia szabálya szerint minden nőnek lassan kell felvonnia a nemzete zászlaját.'::text),
(306417,34047,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jede Nation hat eine Flagge, ... ist jede Flagge von einer Nation.'::text,'also'::text,'aber'::text,'weil'::text,'Jede Nation hat eine Flagge, also ist jede Flagge von einer Nation.'::text),
(306421,34047,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожна нація має прапор, ... кожен прапор — від якоїсь нації.'::text,'тому'::text,'але'::text,'бо'::text,'Кожна нація має прапор, тому кожен прапор — від якоїсь нації.'::text),
(306420,34047,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada nación tiene una bandera, ... cada bandera es de una nación.'::text,'así que'::text,'pero'::text,'porque'::text,'Cada nación tiene una bandera, así que cada bandera es de una nación.'::text),
(306419,34047,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque nation a un drapeau, ... chaque drapeau vient d''une nation.'::text,'donc'::text,'mais'::text,'parce que'::text,'Chaque nation a un drapeau, donc chaque drapeau vient d''une nation.'::text),
(306422,34047,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her ulusun bir bayrağı var, ... her bayrak bir ulusa ait.'::text,'bu yüzden'::text,'ama'::text,'çünkü'::text,'Her ulusun bir bayrağı var, bu yüzden her bayrak bir ulusa ait.'::text),
(306423,34047,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden nemzetnek van zászlaja, ... minden zászló egy nemzeté.'::text,'ezért'::text,'de'::text,'mert'::text,'Minden nemzetnek van zászlaja, ezért minden zászló egy nemzeté.'::text),
(311061,34563,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den Fisch heraus, weil der Fisch im Wasser war.'::text,'zog'::text,'zieht'::text,'ziehen'::text,'Er zog den Fisch heraus, weil der Fisch im Wasser war.'::text),
(311065,34563,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... рибу, бо риба була у воді.'::text,'витягнув'::text,'витягує'::text,'витягувати'::text,'Він витягнув рибу, бо риба була у воді.'::text),
(311064,34563,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el pez porque el pez estaba en el agua.'::text,'Sacó'::text,'Saca'::text,'Sacar'::text,'Sacó el pez porque el pez estaba en el agua.'::text),
(311063,34563,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le poisson parce que le poisson était dans l''eau.'::text,'a sorti'::text,'sort'::text,'sortir'::text,'Il a sorti le poisson parce que le poisson était dans l''eau.'::text),
(311066,34563,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Balığı dışarı ..., çünkü balık sudaydı.'::text,'çekti'::text,'çeker'::text,'çekmek'::text,'Balığı dışarı çekti, çünkü balık sudaydı.'::text),
(311067,34563,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a halat, mert a hal a vízben volt.'::text,'Kihúzta'::text,'Kihúzza'::text,'Kihúzni'::text,'Kihúzta a halat, mert a hal a vízben volt.'::text),
(311070,34564,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ziehst jeden Tag kleine Fische raus, aber gestern ... du einen großen raus. Respekt.'::text,'zogst'::text,'ziehst'::text,NULL::text,'Du ziehst jeden Tag kleine Fische raus, aber gestern zogst du einen großen raus. Respekt.'::text),
(311074,34564,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти щодня витягуєш маленьких рибок, а вчора ... велику. Респект.'::text,'витягнув'::text,'витягуєш'::text,NULL::text,'Ти щодня витягуєш маленьких рибок, а вчора витягнув велику. Респект.'::text),
(311073,34564,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sacas peces pequeños cada día, pero ayer ... uno grande. Respeto.'::text,'sacaste'::text,'sacas'::text,NULL::text,'Sacas peces pequeños cada día, pero ayer sacaste uno grande. Respeto.'::text),
(311072,34564,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu sors des petits poissons tous les jours, mais hier tu ... un gros. Respect.'::text,'as sorti'::text,'sors'::text,NULL::text,'Tu sors des petits poissons tous les jours, mais hier tu as sorti un gros. Respect.'::text),
(311075,34564,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her gün küçük balık çekersin ama dün büyük bir tane ..., saygılar.'::text,'çektin'::text,'çekersin'::text,NULL::text,'Her gün küçük balık çekersin ama dün büyük bir tane çektin, saygılar.'::text),
(311076,34564,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden nap kis halakat húzol ki, de tegnap egy nagyot ... ki. Respekt.'::text,'húztál'::text,'húzol'::text,NULL::text,'Minden nap kis halakat húzol ki, de tegnap egy nagyot húztál ki. Respekt.'::text),
(311088,34566,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sitzt oft und wartet, aber jetzt ... er fest an der Angel.'::text,'zieht'::text,'zieht'::text,NULL::text,'Er sitzt oft und wartet, aber jetzt zieht er fest an der Angel.'::text),
(311092,34566,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він часто сидить і чекає, але зараз він ... щосили за вудку.'::text,'тягне'::text,'тягне'::text,NULL::text,'Він часто сидить і чекає, але зараз він тягне щосили за вудку.'::text),
(311091,34566,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A menudo se sienta y espera, pero ahora ... fuerte de la caña.'::text,'está tirando'::text,'tira'::text,NULL::text,'A menudo se sienta y espera, pero ahora está tirando fuerte de la caña.'::text),
(311090,34566,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il reste souvent assis à attendre, mais là, il ... fort sur la canne.'::text,'est en train de tirer'::text,'tire'::text,NULL::text,'Il reste souvent assis à attendre, mais là, il est en train de tirer fort sur la canne.'::text),
(311093,34566,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çoğu zaman oturup bekler ama şimdi oltayı sıkıca ...'::text,'çekiyor'::text,'çeker'::text,NULL::text,'Çoğu zaman oturup bekler ama şimdi oltayı sıkıca çekiyor.'::text),
(311094,34566,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gyakran csak ül és vár, de most erősen ... a botot.'::text,'húzza'::text,'húzza'::text,NULL::text,'Gyakran csak ül és vár, de most erősen húzza a botot.'::text),
(311097,34567,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, er hat mir erzählt, dass er nächstes Mal einen Hai ...'::text,'rausziehen wird'::text,'rauszieht'::text,'rauszog'::text,'Bestie, er hat mir erzählt, dass er nächstes Mal einen Hai rausziehen wird.'::text),
(311101,34567,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, він сказав мені, що наступного разу ... акулу.'::text,'витягне'::text,'витягує'::text,'витягнув'::text,'Подружко, він сказав мені, що наступного разу витягне акулу.'::text),
(311100,34567,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que la próxima vez ... un tiburón.'::text,'sacará'::text,'saca'::text,'sacó'::text,'Tía, me dijo que la próxima vez sacará un tiburón.'::text),
(311099,34567,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il m''a dit que la prochaine fois il ... un requin.'::text,'sortira'::text,'sort'::text,'a sorti'::text,'Ma belle, il m''a dit que la prochaine fois il sortira un requin.'::text),
(311102,34567,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bana dedi ki bir dahaki sefere köpekbalığı ...'::text,'çekecek'::text,'çeker'::text,'çekti'::text,'Kanka, bana dedi ki bir dahaki sefere köpekbalığı çekecek.'::text),
(311103,34567,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy legközelebb egy cápát ...'::text,'fog kihúzni'::text,'kihúz'::text,'kihúzott'::text,'Csajszi, azt mondta, hogy legközelebb egy cápát fog kihúzni.'::text),
(311106,34568,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, die Angel biegt sich, Alter. Er ... einen riesigen Fisch rausziehen.'::text,'wird'::text,'wird'::text,'zieht'::text,'Yo, die Angel biegt sich, Alter. Er wird einen riesigen Fisch rausziehen.'::text),
(311110,34568,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, вудка гнеться, бро. Він ... величезну рибу.'::text,'збирається витягнути'::text,'витягне'::text,'витягує'::text,'Йо, вудка гнеться, бро. Він збирається витягнути величезну рибу.'::text),
(311109,34568,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, la caña se está doblando, tío. ... un pez enorme.'::text,'Va a sacar'::text,'Sacará'::text,'Saca'::text,'Oye, la caña se está doblando, tío. Va a sacar un pez enorme.'::text),
(311108,34568,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, la canne plie, frère. Il ... un énorme poisson.'::text,'va sortir'::text,'sortira'::text,'sort'::text,'Yo, la canne plie, frère. Il va sortir un énorme poisson.'::text),
(311111,34568,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, olta eğiliyor. Kocaman bir balık ...'::text,'çekecek'::text,'çekecek'::text,'çeker'::text,'Kanka, olta eğiliyor. Kocaman bir balık çekecek.'::text),
(311112,34568,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hé, hajlik a bot, tesó. Egy hatalmas halat ...'::text,'fog kihúzni'::text,'fog kihúzni'::text,'kihúz'::text,'Hé, hajlik a bot, tesó. Egy hatalmas halat fog kihúzni.'::text),
(311115,34569,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Alter, ich wette, er ... morgen mehr Fische rausziehen.'::text,'wird'::text,'wird'::text,NULL::text,'Nee Alter, ich wette, er wird morgen mehr Fische rausziehen.'::text),
(311119,34569,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, спорим, завтра він ... більше риби.'::text,'витягне'::text,'збирається витягнути'::text,NULL::text,'Не, бро, спорим, завтра він витягне більше риби.'::text),
(311118,34569,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, te apuesto a que mañana ... más peces.'::text,'sacará'::text,'va a sacar'::text,NULL::text,'Qué va, tío, te apuesto a que mañana sacará más peces.'::text),
(311117,34569,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non frère, je parie que demain il ... plus de poissons.'::text,'sortira'::text,'va sortir'::text,NULL::text,'Non frère, je parie que demain il sortira plus de poissons.'::text),
(311120,34569,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, bahse girerim yarın daha çok balık ...'::text,'çekecek'::text,'çekecek'::text,NULL::text,'Yok kanka, bahse girerim yarın daha çok balık çekecek.'::text),
(311121,34569,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tesó, fogadok, hogy holnap több halat ...'::text,'fog kihúzni'::text,'fog kihúzni'::text,NULL::text,'Nem, tesó, fogadok, hogy holnap több halat fog kihúzni.'::text),
(320313,35591,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die stärkste Frau der Welt! Absolut!'::text,'ist'::text,'sind'::text,'sein'::text,'Sie ist die stärkste Frau der Welt! Absolut!'::text),
(320317,35591,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... найсильніша жінка у світі! Абсолютно!'::text,'є'::text,'є'::text,'бути'::text,'Вона є найсильніша жінка у світі! Абсолютно!'::text),
(320316,35591,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... la mujer más fuerte del mundo! ¡Totalmente!'::text,'es'::text,'son'::text,'ser'::text,'¡Ella es la mujer más fuerte del mundo! ¡Totalmente!'::text),
(320315,35591,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la femme la plus forte du monde ! Absolument !'::text,'est'::text,'sont'::text,'être'::text,'Elle est la femme la plus forte du monde ! Absolument !'::text),
(320318,35591,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O dünyanın en güçlü kadını ...! Kesinlikle!'::text,''::text,NULL::text,'olmak'::text,'O dünyanın en güçlü kadını! Kesinlikle!'::text),
(320319,35591,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a világ legerősebb nője! Abszolút!'::text,''::text,NULL::text,'lenni'::text,'Ő a világ legerősebb nője! Abszolút!'::text),
(320322,35592,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeden Tag ... sie schwere Seile wie die stärkste Frau der Welt!'::text,'schwingt'::text,'schwingen'::text,'schwingend'::text,'Jeden Tag schwingt sie schwere Seile wie die stärkste Frau der Welt!'::text),
(320326,35592,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щодня вона ... важкими канатами, як найсильніша жінка на світі!'::text,'розмахує'::text,'розмахувати'::text,'розмахуючи'::text,'Щодня вона розмахує важкими канатами, як найсильніша жінка на світі!'::text),
(320325,35592,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Todos los días ... cuerdas pesadas como la mujer más fuerte del mundo!'::text,'agita'::text,'agitar'::text,'agitando'::text,'¡Todos los días agita cuerdas pesadas como la mujer más fuerte del mundo!'::text),
(320324,35592,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque jour, elle ... de lourdes cordes comme la femme la plus forte du monde !'::text,'fait onduler'::text,'faire onduler'::text,'faisant onduler'::text,'Chaque jour, elle fait onduler de lourdes cordes comme la femme la plus forte du monde !'::text),
(320327,35592,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her gün yaşayan en güçlü kadın gibi ağır halatları ...!'::text,'sallar'::text,'sallamak'::text,'sallayarak'::text,'Her gün yaşayan en güçlü kadın gibi ağır halatları sallar!'::text),
(320328,35592,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden nap úgy ... a nehéz köteleket, mint a világ legerősebb nője!'::text,'lengeti'::text,'lengetni'::text,'lengető'::text,'Minden nap úgy lengeti a nehéz köteleket, mint a világ legerősebb nője!'::text),
(320340,35594,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach einem Monat Training ist sie ... als vorher.'::text,'stärker'::text,'stärker'::text,'am stärksten'::text,'Nach einem Monat Training ist sie stärker als vorher.'::text),
(320344,35594,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після місяця тренувань вона ..., ніж раніше.'::text,'сильніша'::text,'більш сильна'::text,'найсильніша'::text,'Після місяця тренувань вона сильніша, ніж раніше.'::text),
(320343,35594,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tras un mes de entrenamiento, está ... que antes.'::text,'más fuerte'::text,'más fuerte'::text,'la más fuerte'::text,'Tras un mes de entrenamiento, está más fuerte que antes.'::text),
(320342,35594,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après un mois d''entraînement, elle est ... qu''avant.'::text,'plus forte'::text,'plus forte'::text,'la plus forte'::text,'Après un mois d''entraînement, elle est plus forte qu''avant.'::text),
(320345,35594,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir aylık antrenmandan sonra eskisinden ...'::text,'daha güçlü'::text,'daha güçlü'::text,'en güçlü'::text,'Bir aylık antrenmandan sonra eskisinden daha güçlü.'::text),
(320346,35594,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy hónap edzés után ..., mint korábban.'::text,'erősebb'::text,'erősebb'::text,'legerősebb'::text,'Egy hónap edzés után erősebb, mint korábban.'::text),
(320349,35595,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, der Trainer sagt, starke Leute ... auf die Box springen. Ehrlich.'::text,'müssen'::text,'müssen'::text,'sollten'::text,'Alter, der Trainer sagt, starke Leute müssen auf die Box springen. Ehrlich.'::text),
(320353,35595,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, тренер каже, що сильні люди ... стрибати на бокс. Без жартів.'::text,'мають'::text,'мусять'::text,'мали б'::text,'Бро, тренер каже, що сильні люди мають стрибати на бокс. Без жартів.'::text),
(320352,35595,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el entrenador dice que la gente fuerte ... saltar al cajón. En serio.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Tío, el entrenador dice que la gente fuerte tiene que saltar al cajón. En serio.'::text),
(320351,35595,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, le coach dit que les gens forts ... sauter sur la box. Sans mentir.'::text,'doivent'::text,'doivent'::text,'devraient'::text,'Frère, le coach dit que les gens forts doivent sauter sur la box. Sans mentir.'::text),
(320354,35595,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, hoca diyor ki güçlü insanlar kutuya ..., yemin ederim.'::text,'atlamak zorunda'::text,'atlamalı'::text,'atlamalı'::text,'Kanka, hoca diyor ki güçlü insanlar kutuya atlamak zorunda, yemin ederim.'::text),
(320355,35595,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az edző szerint az erős embereknek fel ... ugraniuk a dobozra. Komolyan.'::text,'kell'::text,'kell'::text,'kellene'::text,'Tesó, az edző szerint az erős embereknek fel kell ugraniuk a dobozra. Komolyan.'::text),
(320358,35596,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, wenn du stark sein willst, ... du diesen Box Jump probieren.'::text,'solltest'::text,'sollst'::text,'solltest'::text,'Yo, wenn du stark sein willst, solltest du diesen Box Jump probieren.'::text),
(320362,35596,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, якщо хочеш бути сильним, ти ... спробувати той стрибок на бокс.'::text,'мав би'::text,'будеш'::text,'мав би'::text,'Йо, якщо хочеш бути сильним, ти мав би спробувати той стрибок на бокс.'::text),
(320361,35596,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, si quieres estar fuerte, ... probar ese salto al cajón.'::text,'deberías'::text,'deberás'::text,'deberías'::text,'Oye, si quieres estar fuerte, deberías probar ese salto al cajón.'::text),
(320360,35596,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, si tu veux être fort, tu ... essayer ce box jump.'::text,'devrais'::text,'devras'::text,'devrais'::text,'Yo, si tu veux être fort, tu devrais essayer ce box jump.'::text),
(320363,35596,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, güçlü olmak istiyorsan o kutu atlamayı ...'::text,'denemelisin'::text,'deneyeceksin'::text,'denemelisin'::text,'Kanka, güçlü olmak istiyorsan o kutu atlamayı denemelisin.'::text),
(320364,35596,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hé, ha erős akarsz lenni, ki ... próbálnod azt a dobozugrást.'::text,'kellene'::text,'kell'::text,'kellene'::text,'Hé, ha erős akarsz lenni, ki kellene próbálnod azt a dobozugrást.'::text),
(320376,35598,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kettlebell ist schwer, ... sie ist stark, also geht sie hoch.'::text,'aber'::text,'also'::text,'weil'::text,'Die Kettlebell ist schwer, aber sie ist stark, also geht sie hoch.'::text),
(320380,35598,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гиря важка, ... вона сильна, тому гиря йде вгору.'::text,'але'::text,'тому'::text,'бо'::text,'Гиря важка, але вона сильна, тому гиря йде вгору.'::text),
(320379,35598,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pesa rusa pesa mucho, ... ella es fuerte, así que sube.'::text,'pero'::text,'así que'::text,'porque'::text,'La pesa rusa pesa mucho, pero ella es fuerte, así que sube.'::text),
(320378,35598,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le kettlebell est lourd, ... elle est forte, donc il monte.'::text,'mais'::text,'donc'::text,'parce que'::text,'Le kettlebell est lourd, mais elle est forte, donc il monte.'::text),
(320381,35598,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kettlebell ağır ... o güçlü, bu yüzden yukarı kalkıyor.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Kettlebell ağır ama o güçlü, bu yüzden yukarı kalkıyor.'::text),
(320382,35598,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kettlebell nehéz, ... ő erős, ezért felmegy.'::text,'de'::text,'ezért'::text,'mert'::text,'A kettlebell nehéz, de ő erős, ezért felmegy.'::text),
(312312,34702,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Letzten Sommer ... sie mit einer Gummiente auf einem Salzsee.'::text,'entspannte sich'::text,'entspannt sich'::text,'entspannt sich'::text,'Letzten Sommer entspannte sich sie mit einer Gummiente auf einem Salzsee.'::text),
(312316,34702,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Минулого літа вона ... на солоному озері з гумовою качечкою.'::text,'відпочивала'::text,'відпочиває'::text,'відпочиває'::text,'Минулого літа вона відпочивала на солоному озері з гумовою качечкою.'::text),
(312315,34702,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El verano pasado ... en un lago salado con un patito de goma.'::text,'se relajó'::text,'se relaja'::text,'se relaja'::text,'El verano pasado se relajó en un lago salado con un patito de goma.'::text),
(312314,34702,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''été dernier, elle ... sur un lac salé avec un canard en plastique.'::text,'s''est détendue'::text,'se détend'::text,'se détend'::text,'L''été dernier, elle s''est détendue sur un lac salé avec un canard en plastique.'::text),
(312317,34702,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geçen yaz lastik bir ördekle tuz gölünde ...'::text,'dinlendi'::text,'dinlenir'::text,'dinlenir'::text,'Geçen yaz lastik bir ördekle tuz gölünde dinlendi.'::text),
(312318,34702,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavaly nyáron egy gumikacsával ... egy sós tavon.'::text,'pihent'::text,'pihen'::text,'pihen'::text,'Tavaly nyáron egy gumikacsával pihent egy sós tavon.'::text),
(312321,34703,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wellness-KPI: Sie entspannt sich täglich 1 Stunde, aber gestern ... sie sich den ganzen Nachmittag.'::text,'entspannte'::text,'entspannt'::text,NULL::text,'Wellness-KPI: Sie entspannt sich täglich 1 Stunde, aber gestern entspannte sie sich den ganzen Nachmittag.'::text),
(312325,34703,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wellness-KPI: вона відпочиває 1 годину на день, але вчора ... всю другу половину дня.'::text,'відпочивала'::text,'відпочиває'::text,NULL::text,'Wellness-KPI: вона відпочиває 1 годину на день, але вчора відпочивала всю другу половину дня.'::text),
(312324,34703,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'KPI de bienestar: se relaja 1 hora al día, pero ayer ... toda la tarde.'::text,'se relajó'::text,'se relaja'::text,NULL::text,'KPI de bienestar: se relaja 1 hora al día, pero ayer se relajó toda la tarde.'::text),
(312323,34703,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'KPI bien-être : elle se détend 1 heure par jour, mais hier elle ... tout l''après-midi.'::text,'s''est détendue'::text,'se détend'::text,NULL::text,'KPI bien-être : elle se détend 1 heure par jour, mais hier elle s''est détendue tout l''après-midi.'::text),
(312326,34703,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wellness KPI''ı: günde 1 saat dinlenir ama dün bütün öğleden sonra ...'::text,'dinlendi'::text,'dinlenir'::text,NULL::text,'Wellness KPI''ı: günde 1 saat dinlenir ama dün bütün öğleden sonra dinlendi.'::text),
(312327,34703,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wellness-KPI: napi 1 órát pihen, de tegnap egész délután ...'::text,'pihent'::text,'pihen'::text,NULL::text,'Wellness-KPI: napi 1 órát pihen, de tegnap egész délután pihent.'::text),
(312330,34704,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... sich jetzt auf dem Wasser, weil Wasser zum Entspannen da ist.'::text,'entspannt'::text,'entspannt'::text,'entspannt'::text,'Sie entspannt sich jetzt auf dem Wasser, weil Wasser zum Entspannen da ist.'::text),
(312334,34704,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона зараз ... на воді, бо вода — для відпочинку.'::text,'відпочиває'::text,'відпочиває'::text,'відпочиває'::text,'Вона зараз відпочиває на воді, бо вода — для відпочинку.'::text),
(312333,34704,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora ... en el agua, porque el agua es para relajarse.'::text,'se está relajando'::text,'se relaja'::text,'se está relajando'::text,'Ahora se está relajando en el agua, porque el agua es para relajarse.'::text),
(312332,34704,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... sur l''eau maintenant, parce que l''eau, c''est pour se détendre.'::text,'est en train de se détendre'::text,'se détend'::text,'est en train de se détendre'::text,'Elle est en train de se détendre sur l''eau maintenant, parce que l''eau, c''est pour se détendre.'::text),
(312335,34704,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu an suyun üstünde ..., çünkü su dinlenmek içindir.'::text,'dinleniyor'::text,'dinlenir'::text,'dinleniyor'::text,'Şu an suyun üstünde dinleniyor, çünkü su dinlenmek içindir.'::text),
(312336,34704,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most a vízen ..., mert a víz pihenésre való.'::text,'pihen'::text,'pihen'::text,'pihen'::text,'Most a vízen pihen, mert a víz pihenésre való.'::text),
(312339,34705,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie entspannt sich nie, aber jetzt ... sie sich auf dem Wasser! Absolut schockierend!'::text,'entspannt'::text,'entspannt'::text,NULL::text,'Sie entspannt sich nie, aber jetzt entspannt sie sich auf dem Wasser! Absolut schockierend!'::text),
(312343,34705,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ніколи не відпочиває, а зараз ... на воді! Просто шок!'::text,'відпочиває'::text,'відпочиває'::text,NULL::text,'Вона ніколи не відпочиває, а зараз відпочиває на воді! Просто шок!'::text),
(312342,34705,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nunca se relaja, pero ahora ... en el agua! ¡Totalmente impactante!'::text,'se está relajando'::text,'se relaja'::text,NULL::text,'¡Nunca se relaja, pero ahora se está relajando en el agua! ¡Totalmente impactante!'::text),
(312341,34705,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ne se détend jamais, mais là, elle ... sur l''eau ! Absolument choquant !'::text,'est en train de se détendre'::text,'se détend'::text,NULL::text,'Elle ne se détend jamais, mais là, elle est en train de se détendre sur l''eau ! Absolument choquant !'::text),
(312344,34705,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Asla dinlenmez ama şimdi suyun üstünde ...! Resmen şok!'::text,'dinleniyor'::text,'dinlenir'::text,NULL::text,'Asla dinlenmez ama şimdi suyun üstünde dinleniyor! Resmen şok!'::text),
(312345,34705,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha nem pihen, de most a vízen ...! Teljesen sokkoló!'::text,'pihen'::text,'pihen'::text,NULL::text,'Soha nem pihen, de most a vízen pihen! Teljesen sokkoló!'::text),
(312348,34706,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn mich diese Ente beißt, ... ich mich nie wieder entspannen!'::text,'werde'::text,'bin'::text,NULL::text,'Wenn mich diese Ente beißt, werde ich mich nie wieder entspannen!'::text),
(312352,34706,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ця качка мене вкусить, я більше ніколи не ... відпочивати!'::text,'буду'::text,'є'::text,NULL::text,'Якщо ця качка мене вкусить, я більше ніколи не буду відпочивати!'::text),
(312351,34706,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si este pato me muerde, nunca más ... me relajaré!'::text,''::text,'estoy'::text,NULL::text,'¡Si este pato me muerde, nunca más me relajaré!'::text),
(312350,34706,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ce canard me mord, je ne ... me détendrai plus jamais !'::text,''::text,'suis'::text,NULL::text,'Si ce canard me mord, je ne me détendrai plus jamais !'::text),
(312353,34706,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu ördek beni ısırırsa bir daha asla ...!'::text,'dinlenmeyeceğim'::text,NULL::text,NULL::text,'Bu ördek beni ısırırsa bir daha asla dinlenmeyeceğim!'::text),
(312354,34706,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ez a kacsa megharap, soha többé nem ... pihenni!'::text,'fogok'::text,'vagyok'::text,NULL::text,'Ha ez a kacsa megharap, soha többé nem fogok pihenni!'::text),
(312357,34707,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das war''s, ich hab''s gerade entschieden! Ich ... mich für immer auf diesem See entspannen!'::text,'werde'::text,'werde'::text,NULL::text,'Das war''s, ich hab''s gerade entschieden! Ich werde mich für immer auf diesem See entspannen!'::text),
(312361,34707,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Усе, я щойно вирішила! Я ... відпочивати на цьому озері вічно!'::text,'буду'::text,'збираюся'::text,NULL::text,'Усе, я щойно вирішила! Я буду відпочивати на цьому озері вічно!'::text),
(312360,34707,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Se acabó, lo acabo de decidir! ¡Yo ... me relajaré en este lago para siempre!'::text,''::text,'voy a'::text,NULL::text,'¡Se acabó, lo acabo de decidir! ¡Yo me relajaré en este lago para siempre!'::text),
(312359,34707,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est décidé, je viens de trancher ! Je ... me détendrai sur ce lac pour toujours !'::text,''::text,'vais'::text,NULL::text,'C''est décidé, je viens de trancher ! Je me détendrai sur ce lac pour toujours !'::text),
(312362,34707,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, az önce karar verdim! Sonsuza kadar bu gölde ...!'::text,'dinleneceğim'::text,'dinleneceğim'::text,NULL::text,'Tamam, az önce karar verdim! Sonsuza kadar bu gölde dinleneceğim!'::text),
(312363,34707,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ennyi, most döntöttem el! Örökké ezen a tavon ... pihenni!'::text,'fogok'::text,'fogok'::text,NULL::text,'Ennyi, most döntöttem el! Örökké ezen a tavon fogok pihenni!'::text),
(309342,34372,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Fotografen hier hören nie auf zu fotografieren! Absolut unglaublich!'::text,'Diese'::text,'Dieser'::text,'Jener'::text,'Diese Fotografen hier hören nie auf zu fotografieren! Absolut unglaublich!'::text),
(309346,34372,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... фотографи тут ніколи не перестають знімати! Просто неймовірно!'::text,'Ці'::text,'Цей'::text,'Той'::text,'Ці фотографи тут ніколи не перестають знімати! Просто неймовірно!'::text),
(309345,34372,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... fotógrafos de aquí nunca dejan de disparar! ¡Absolutamente increíble!'::text,'Estos'::text,'Este'::text,'Ese'::text,'¡Estos fotógrafos de aquí nunca dejan de disparar! ¡Absolutamente increíble!'::text),
(309344,34372,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... photographes ne s''arrêtent jamais de shooter ! Absolument incroyable !'::text,'Ces'::text,'Ce'::text,'Ce'::text,'Ces photographes ne s''arrêtent jamais de shooter ! Absolument incroyable !'::text),
(309347,34372,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buradaki ... fotoğrafçılar çekmeyi hiç bırakmıyor! Kesinlikle inanılmaz!'::text,'bu'::text,'bu'::text,'şu'::text,'Buradaki bu fotoğrafçılar çekmeyi hiç bırakmıyor! Kesinlikle inanılmaz!'::text),
(309348,34372,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fotósok itt sosem hagyják abba a fotózást! Hihetetlen!'::text,'Ezek a'::text,'Ez a'::text,'Az a'::text,'Ezek a fotósok itt sosem hagyják abba a fotózást! Hihetetlen!'::text),
(309360,34374,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Jumbojet donnert direkt ... die Köpfe der Fotografen!'::text,'über'::text,'unter'::text,'in'::text,'Der Jumbojet donnert direkt über die Köpfe der Fotografen!'::text),
(309364,34374,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Джамбо-джет реве прямо ... головами фотографів!'::text,'над'::text,'під'::text,'у'::text,'Джамбо-джет реве прямо над головами фотографів!'::text),
(309363,34374,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El jumbo ruge justo ... la cabeza de los fotógrafos!'::text,'por encima de'::text,'debajo de'::text,'en'::text,'¡El jumbo ruge justo por encima de la cabeza de los fotógrafos!'::text),
(309362,34374,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jumbo-jet hurle juste ... la tête des photographes !'::text,'au-dessus de'::text,'sous'::text,'dans'::text,'Le jumbo-jet hurle juste au-dessus de la tête des photographes !'::text),
(309365,34374,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jumbo jet tam fotoğrafçıların kafalarının ... çığlık atarak geçiyor!'::text,'üstünden'::text,'altından'::text,'içinden'::text,'Jumbo jet tam fotoğrafçıların kafalarının üstünden çığlık atarak geçiyor!'::text),
(309366,34374,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A jumbo jet közvetlenül a fotósok ... süvít el!'::text,'feje fölött'::text,'feje alatt'::text,'fejében'::text,'A jumbo jet közvetlenül a fotósok feje fölött süvít el!'::text),
(309369,34375,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Da sind zwei Fotografen, und jeder hat ... Stativ.'::text,'ein'::text,'erstes'::text,'einmal'::text,'Da sind zwei Fotografen, und jeder hat ein Stativ.'::text),
(309373,34375,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Там двоє фотографів, і в кожного ... штатив.'::text,'один'::text,'перший'::text,'один раз'::text,'Там двоє фотографів, і в кожного один штатив.'::text),
(309372,34375,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hay dos fotógrafos y cada uno tiene ... trípode.'::text,'un'::text,'primer'::text,'una vez'::text,'Hay dos fotógrafos y cada uno tiene un trípode.'::text),
(309371,34375,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il y a deux photographes, et chacun a ... trépied.'::text,'un'::text,'premier'::text,'une fois'::text,'Il y a deux photographes, et chacun a un trépied.'::text),
(309374,34375,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki fotoğrafçı var ve her birinin ... tripodu var.'::text,'bir'::text,'birinci'::text,'bir kez'::text,'İki fotoğrafçı var ve her birinin bir tripodu var.'::text),
(309375,34375,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két fotós van, és mindegyiknek ... állványa van.'::text,'egy'::text,'első'::text,'egyszer'::text,'Két fotós van, és mindegyiknek egy állványa van.'::text),
(309378,34376,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend haben die Fotografen so viel ... in ihren Taschen.'::text,'Ausrüstung'::text,'Ausrüstung'::text,'eine Ausrüstung'::text,'Mädel, anscheinend haben die Fotografen so viel Ausrüstung in ihren Taschen.'::text),
(309382,34376,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, у фотографів стільки ... в сумках.'::text,'обладнання'::text,'обладнання'::text,'обладнання'::text,'Подруго, кажуть, у фотографів стільки обладнання в сумках.'::text),
(309381,34376,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, parece que los fotógrafos llevan tanto ... en las bolsas.'::text,'equipo'::text,'equipo'::text,'un equipo'::text,'Tía, parece que los fotógrafos llevan tanto equipo en las bolsas.'::text),
(309380,34376,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment les photographes ont tellement de ... dans leurs sacs.'::text,'matériel'::text,'matériel'::text,'un matériel'::text,'Ma belle, apparemment les photographes ont tellement de matériel dans leurs sacs.'::text),
(309383,34376,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre fotoğrafçıların çantalarında çok fazla ... varmış.'::text,'ekipman'::text,'ekipmanlar'::text,'bir ekipman'::text,'Kızım, duyduğuma göre fotoğrafçıların çantalarında çok fazla ekipman varmış.'::text),
(309384,34376,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a fotósoknak annyi ... van a táskájukban.'::text,'felszerelésük'::text,'felszerelésük'::text,'egy felszerelésük'::text,'Csajszi, állítólag a fotósoknak annyi felszerelésük van a táskájukban.'::text),
(309387,34377,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ich hab gehört, ein Fotograf hat ... Fotos von dem Jet gemacht.'::text,'eine Menge'::text,'viel'::text,'ein bisschen'::text,'Hör zu, ich hab gehört, ein Fotograf hat eine Menge Fotos von dem Jet gemacht.'::text),
(309391,34377,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що один фотограф зробив ... фото того літака.'::text,'багато'::text,'багато'::text,'трохи'::text,'Слухай, я чула, що один фотограф зробив багато фото того літака.'::text),
(309390,34377,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me han dicho que un fotógrafo hizo ... fotos de ese avión.'::text,'un montón de'::text,'mucha'::text,'un poco de'::text,'Escucha, me han dicho que un fotógrafo hizo un montón de fotos de ese avión.'::text),
(309389,34377,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire qu''un photographe a pris ... photos de cet avion.'::text,'plein de'::text,'beaucoup de'::text,'un peu de'::text,'Écoute, j''ai entendu dire qu''un photographe a pris plein de photos de cet avion.'::text),
(309392,34377,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki bir fotoğrafçı o uçağın ... fotoğrafını çekmiş.'::text,'çok'::text,'çok'::text,'biraz'::text,'Dinle, duydum ki bir fotoğrafçı o uçağın çok fotoğrafını çekmiş.'::text),
(309393,34377,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy egy fotós ... fotót csinált arról a gépről.'::text,'rengeteg'::text,'sok'::text,'egy kis'::text,'Figyelj, azt hallottam, hogy egy fotós rengeteg fotót csinált arról a gépről.'::text),
(309396,34378,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Am Ende der Landebahn ... zwei Fotografen.'::text,'sind'::text,'ist'::text,'sein'::text,'Am Ende der Landebahn sind zwei Fotografen.'::text),
(309400,34378,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У кінці злітної смуги ... двоє фотографів.'::text,'є'::text,'є'::text,'бути'::text,'У кінці злітної смуги є двоє фотографів.'::text),
(309399,34378,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... dos fotógrafos al final de la pista.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay dos fotógrafos al final de la pista.'::text),
(309398,34378,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... deux photographes au bout de la piste.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a deux photographes au bout de la piste.'::text),
(309401,34378,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pistin sonunda iki fotoğrafçı ...'::text,'var'::text,'var'::text,'olmak'::text,'Pistin sonunda iki fotoğrafçı var.'::text),
(309402,34378,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kifutópálya végén két fotós ...'::text,'van'::text,'van'::text,'lenni'::text,'A kifutópálya végén két fotós van.'::text),
(314544,34950,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jede Möwe liebt dich und deine zwei ... Brot. So cool.'::text,'Stücke'::text,'Stück'::text,'Stücke'::text,'Jede Möwe liebt dich und deine zwei Stücke Brot. So cool.'::text),
(314548,34950,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожна чайка любить тебе і твої два ... хліба. Дуже круто.'::text,'шматки'::text,'шматок'::text,'шматки'::text,'Кожна чайка любить тебе і твої два шматки хліба. Дуже круто.'::text),
(314547,34950,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todas las gaviotas te quieren a ti y a tus dos ... de pan. Qué guay.'::text,'trozos'::text,'trozo'::text,'trozos'::text,'Todas las gaviotas te quieren a ti y a tus dos trozos de pan. Qué guay.'::text),
(314546,34950,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque mouette t''adore, toi et tes deux ... de pain. Trop cool.'::text,'morceaux'::text,'morceau'::text,'morceaux'::text,'Chaque mouette t''adore, toi et tes deux morceaux de pain. Trop cool.'::text),
(314549,34950,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her martı seni ve iki ... ekmeğini seviyor. Çok havalı.'::text,'parça'::text,'parça'::text,'parça'::text,'Her martı seni ve iki parça ekmeğini seviyor. Çok havalı.'::text),
(314550,34950,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden sirály imád téged és a két ... kenyeredet. Nagyon menő.'::text,'darab'::text,'darab'::text,'darab'::text,'Minden sirály imád téged és a két darab kenyeredet. Nagyon menő.'::text),
(314553,34951,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der weiß-graue Vogel ist ... Möwe, keine Taube.'::text,'eine'::text,'eine'::text,'die'::text,'Der weiß-graue Vogel ist eine Möwe, keine Taube.'::text),
(314557,34951,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Біло-сірий птах — це ... чайка, а не голуб.'::text,''::text,NULL::text,NULL::text,'Біло-сірий птах — це чайка, а не голуб.'::text),
(314556,34951,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pájaro blanco y gris es ... gaviota, no una paloma.'::text,'una'::text,'una'::text,'la'::text,'El pájaro blanco y gris es una gaviota, no una paloma.'::text),
(314555,34951,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''oiseau blanc et gris est ... mouette, pas un pigeon.'::text,'une'::text,'une'::text,'la'::text,'L''oiseau blanc et gris est une mouette, pas un pigeon.'::text),
(314558,34951,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beyaz-gri kuş ... martı, güvercin değil.'::text,'bir'::text,'bir'::text,NULL::text,'Beyaz-gri kuş bir martı, güvercin değil.'::text),
(314559,34951,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fehér-szürke madár ... sirály, nem galamb.'::text,'egy'::text,'egy'::text,'a'::text,'A fehér-szürke madár egy sirály, nem galamb.'::text),
(314571,34953,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine Möwe fliegt nah an ... Schiebermütze vorbei.'::text,'seiner'::text,'ihrer'::text,'seiner'::text,'Eine Möwe fliegt nah an seiner Schiebermütze vorbei.'::text),
(314575,34953,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чайка літає біля ... кашкета.'::text,'його'::text,'її'::text,'його'::text,'Чайка літає біля його кашкета.'::text),
(314574,34953,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una gaviota vuela cerca de ... gorra plana.'::text,'su'::text,'su'::text,'su'::text,'Una gaviota vuela cerca de su gorra plana.'::text),
(314573,34953,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une mouette vole près de ... casquette plate.'::text,'sa'::text,'sa'::text,'sa'::text,'Une mouette vole près de sa casquette plate.'::text),
(314576,34953,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir martı ... kasketinin yakınında uçuyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Bir martı onun kasketinin yakınında uçuyor.'::text),
(314577,34953,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy sirály repül a ... közelében.'::text,'sapkája'::text,'sapkája'::text,'sapkája'::text,'Egy sirály repül a sapkája közelében.'::text),
(314580,34954,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hilfe! Zwölf Möwen fliegen ... der Luft um mich herum! Ein Albtraum!'::text,'in'::text,'auf'::text,'an'::text,'Hilfe! Zwölf Möwen fliegen in der Luft um mich herum! Ein Albtraum!'::text),
(314584,34954,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рятуйте! Дванадцять чайок літають ... повітрі навколо мене! Жах!'::text,'у'::text,'на'::text,'біля'::text,'Рятуйте! Дванадцять чайок літають у повітрі навколо мене! Жах!'::text),
(314583,34954,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Socorro! ¡Doce gaviotas vuelan ... el aire a mi alrededor! ¡Una pesadilla!'::text,'por'::text,'sobre'::text,'a'::text,'¡Socorro! ¡Doce gaviotas vuelan por el aire a mi alrededor! ¡Una pesadilla!'::text),
(314582,34954,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À l''aide ! Douze mouettes volent ... les airs autour de moi ! Un cauchemar !'::text,'dans'::text,'sur'::text,'à'::text,'À l''aide ! Douze mouettes volent dans les airs autour de moi ! Un cauchemar !'::text),
(314585,34954,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İmdat! On iki martı etrafımda ... uçuşuyor! Tam bir kâbus!'::text,'havada'::text,'havanın üstünde'::text,NULL::text,'İmdat! On iki martı etrafımda havada uçuşuyor! Tam bir kâbus!'::text),
(314586,34954,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Segítség! Tizenkét sirály repül a ... körülöttem! Rémálom!'::text,'levegőben'::text,'levegőn'::text,'levegőnél'::text,'Segítség! Tizenkét sirály repül a levegőben körülöttem! Rémálom!'::text),
(314589,34955,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zuerst ist da eine Möwe, und dann sind es ...'::text,'zwölf'::text,'zwölfte'::text,'Zwölfen'::text,'Zuerst ist da eine Möwe, und dann sind es zwölf.'::text),
(314593,34955,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Спочатку там одна чайка, а потім їх ...'::text,'дванадцять'::text,'дванадцята'::text,'дванадцятки'::text,'Спочатку там одна чайка, а потім їх дванадцять.'::text),
(314592,34955,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al principio hay una gaviota, y luego hay ...'::text,'doce'::text,'duodécima'::text,'doce'::text,'Al principio hay una gaviota, y luego hay doce.'::text),
(314591,34955,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''abord, il y a une mouette, et ensuite il y en a ...'::text,'douze'::text,'douzième'::text,'douze'::text,'D''abord, il y a une mouette, et ensuite il y en a douze.'::text),
(314594,34955,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Önce bir martı var, sonra ... oluyor.'::text,'on iki'::text,'on ikinci'::text,'on ikiler'::text,'Önce bir martı var, sonra on iki oluyor.'::text),
(314595,34955,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Először egy sirály van, aztán ...'::text,'tizenkettő'::text,'tizenkettedik'::text,'tizenkettesek'::text,'Először egy sirály van, aztán tizenkettő.'::text),
(314607,34957,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, ... Möwen wollen dein Brot. Respekt.'::text,'viele'::text,'viel'::text,'ein bisschen'::text,'Ehrlich, viele Möwen wollen dein Brot. Respekt.'::text),
(314611,34957,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ... чайок хочуть твого хліба. Респект.'::text,'багато'::text,'багато'::text,'трохи'::text,'Чесно, багато чайок хочуть твого хліба. Респект.'::text),
(314610,34957,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ... gaviotas quieren tu pan. Respeto.'::text,'muchas'::text,'mucha'::text,'un poco de'::text,'La verdad, muchas gaviotas quieren tu pan. Respeto.'::text),
(314609,34957,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ... mouettes veulent ton pain. Respect.'::text,'beaucoup de'::text,'beaucoup de'::text,'un peu de'::text,'Franchement, beaucoup de mouettes veulent ton pain. Respect.'::text),
(314612,34957,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, ... martı ekmeğini istiyor. Saygılar.'::text,'çok'::text,'çok'::text,'biraz'::text,'Açıkçası, çok martı ekmeğini istiyor. Saygılar.'::text),
(314613,34957,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ... sirály akarja a kenyeredet. Respekt.'::text,'sok'::text,'sok'::text,'egy kis'::text,'Őszintén, sok sirály akarja a kenyeredet. Respekt.'::text),
(297966,33108,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, die Führerin ... einen gelben Regenschirm, dem muss man folgen.'::text,'hat'::text,'haben'::text,'hat'::text,'Alter, die Führerin hat einen gelben Regenschirm, dem muss man folgen.'::text),
(297970,33108,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, екскурсоводка ... жовту парасольку, треба йти за нею.'::text,'має'::text,'мають'::text,'має'::text,'Бро, екскурсоводка має жовту парасольку, треба йти за нею.'::text),
(297969,33108,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, la guía ... un paraguas amarillo, hay que seguirlo.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'Tío, la guía tiene un paraguas amarillo, hay que seguirlo.'::text),
(297968,33108,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, la guide ... un parapluie jaune, faut le suivre.'::text,'a'::text,'ont'::text,'a'::text,'Frère, la guide a un parapluie jaune, faut le suivre.'::text),
(297971,33108,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, rehberin sarı bir şemsiyesi ..., onu takip etmek lazım.'::text,'var'::text,'var'::text,'var'::text,'Kanka, rehberin sarı bir şemsiyesi var, onu takip etmek lazım.'::text),
(297972,33108,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az idegenvezetőnek ... egy sárga esernyője, azt kell követni.'::text,'van'::text,'van'::text,'van'::text,'Tesó, az idegenvezetőnek van egy sárga esernyője, azt kell követni.'::text),
(297984,33110,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeder ... den gelben Regenschirm der Führerin sehen.'::text,'kann'::text,'kann'::text,'ist'::text,'Jeder kann den gelben Regenschirm der Führerin sehen.'::text),
(297988,33110,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожен ... бачити жовту парасольку екскурсоводки.'::text,'може'::text,'може'::text,'є'::text,'Кожен може бачити жовту парасольку екскурсоводки.'::text),
(297987,33110,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo el mundo ... ver el paraguas amarillo de la guía.'::text,'puede'::text,'puede'::text,'está'::text,'Todo el mundo puede ver el paraguas amarillo de la guía.'::text),
